  1→import { z } from "zod";
  2→import { ServerContext } from "../server.js";
  3→import { CACHE_TTLS, ReplicantError, ErrorCode } from "../types/index.js";
  4→
  5→export const adbAppInputSchema = z.object({
  6→  operation: z.enum(["install", "uninstall", "launch", "stop", "clear-data", "list"]),
  7→  apkPath: z.string().optional(),
  8→  packageName: z.string().optional(),
  9→  // List operation options
 10→  limit: z.number().min(1).max(100).optional(),
 11→  filter: z.string().optional(),
 12→  offset: z.number().min(0).optional(),
 13→});
 14→
 15→export type AdbAppInput = z.infer<typeof adbAppInputSchema>;
 16→
 17→async function handleInstall(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 18→  if (!input.apkPath) {
 19→    throw new ReplicantError(
 20→      ErrorCode.INPUT_VALIDATION_FAILED,
 21→      "apkPath is required for install operation",
 22→      "Provide the path to the APK file to install",
 23→    );
 24→  }
 25→  await context.adb.install(deviceId, input.apkPath);
 26→  return { installed: input.apkPath, deviceId };
 27→}
 28→
 29→async function handleUninstall(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 30→  if (!input.packageName) {
 31→    throw new ReplicantError(
 32→      ErrorCode.INPUT_VALIDATION_FAILED,
 33→      "packageName is required for uninstall operation",
 34→      "Provide the package name to uninstall",
 35→    );
 36→  }
 37→  await context.adb.uninstall(deviceId, input.packageName);
 38→  return { uninstalled: input.packageName, deviceId };
 39→}
 40→
 41→async function handleLaunch(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 42→  if (!input.packageName) {
 43→    throw new ReplicantError(
 44→      ErrorCode.INPUT_VALIDATION_FAILED,
 45→      "packageName is required for launch operation",
 46→      "Provide the package name to launch",
 47→    );
 48→  }
 49→  await context.adb.launch(deviceId, input.packageName);
 50→  return { launched: input.packageName, deviceId };
 51→}
 52→
 53→async function handleStop(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 54→  if (!input.packageName) {
 55→    throw new ReplicantError(
 56→      ErrorCode.INPUT_VALIDATION_FAILED,
 57→      "packageName is required for stop operation",
 58→      "Provide the package name to stop",
 59→    );
 60→  }
 61→  await context.adb.stop(deviceId, input.packageName);
 62→  return { stopped: input.packageName, deviceId };
 63→}
 64→
 65→async function handleClearData(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 66→  if (!input.packageName) {
 67→    throw new ReplicantError(
 68→      ErrorCode.INPUT_VALIDATION_FAILED,
 69→      "packageName is required for clear-data operation",
 70→      "Provide the package name to clear data for",
 71→    );
 72→  }
 73→  await context.adb.clearData(deviceId, input.packageName);
 74→  return { cleared: input.packageName, deviceId };
 75→}
 76→
 77→async function handleList(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 78→  const allPackages = await context.adb.getPackages(deviceId);
 79→  const limit = input.limit ?? 20;
 80→  const offset = input.offset ?? 0;
 81→  const filter = input.filter?.toLowerCase();
 82→
 83→  const filtered = filter
 84→    ? allPackages.filter((pkg) => pkg.toLowerCase().includes(filter))
 85→    : allPackages;
 86→
 87→  const paginated = filtered.slice(offset, offset + limit);
 88→  const hasMore = offset + limit < filtered.length;
 89→
 90→  const cacheId = context.cache.generateId("app-list");
 91→  context.cache.set(
 92→    cacheId,
 93→    { packages: filtered, deviceId, filter: filter || null },
 94→    "app-list",
 95→    CACHE_TTLS.APP_LIST
 96→  );
 97→
 98→  return {
 99→    packages: paginated,
100→    count: paginated.length,
101→    totalCount: filtered.length,
102→    hasMore,
103→    offset,
104→    limit,
105→    cacheId,
106→    deviceId,
107→  };
108→}
109→
110→type AppHandler = (input: AdbAppInput, deviceId: string, context: ServerContext) => Promise<Record<string, unknown>>;
111→
112→const operations: Record<string, AppHandler> = {
113→  install: handleInstall,
114→  uninstall: handleUninstall,
115→  launch: handleLaunch,
116→  stop: handleStop,
117→  "clear-data": handleClearData,
118→  list: handleList,
119→};
