121→export async function handleAdbAppTool(
122→  input: AdbAppInput,
123→  context: ServerContext
124→): Promise<Record<string, unknown>> {
125→  const device = await context.deviceState.ensureDevice(context.adb);
126→  const handler = operations[input.operation];
127→  if (!handler) {
128→    throw new ReplicantError(
129→      ErrorCode.INVALID_OPERATION,
130→      `Unknown operation: ${input.operation}`,
131→      "Valid operations: install, uninstall, launch, stop, clear-data, list",
132→    );
133→  }
134→  return handler(input, device.id, context);
135→}
