  3→import { parseDeviceList, parsePackageList } from "../parsers/adb-output.js";
  4→
  5→export class AdbAdapter {
  6→  constructor(private runner: ProcessRunner = new ProcessRunner()) {}
  7→
  8→  async getDevices(): Promise<Device[]> {
  9→    const result = await this.adb(["devices"]);
 10→    return parseDeviceList(result.stdout);
 11→  }
 12→
 13→  async getPackages(deviceId: string): Promise<string[]> {
 14→    const result = await this.adb(["-s", deviceId, "shell", "pm", "list", "packages"]);
 15→    return parsePackageList(result.stdout);
 16→  }
 17→
 18→  async install(deviceId: string, apkPath: string): Promise<void> {
 19→    const result = await this.adb(["-s", deviceId, "install", "-r", apkPath]);
 20→    if (result.exitCode !== 0 || result.stdout.includes("Failure")) {
 21→      throw new ReplicantError(
 22→        ErrorCode.INSTALL_FAILED,
 23→        `Failed to install APK: ${result.stdout}`,
 24→        "Check the APK path and device state"
 25→      );
 26→    }
 27→  }
 28→
 29→  async uninstall(deviceId: string, packageName: string): Promise<void> {
 30→    const result = await this.adb(["-s", deviceId, "uninstall", packageName]);
 31→    if (result.exitCode !== 0) {
 32→      throw new ReplicantError(
 33→        ErrorCode.PACKAGE_NOT_FOUND,
 34→        `Failed to uninstall ${packageName}`,
 35→        "Check the package name"
 36→      );
 37→    }
 38→  }
 39→
 40→  async launch(deviceId: string, packageName: string): Promise<void> {
 41→    // Get the main activity using dumpsys
 42→    const result = await this.adb([
 43→      "-s", deviceId, "shell", "monkey",
 44→      "-p", packageName, "-c", "android.intent.category.LAUNCHER", "1"
 45→    ]);
 46→    if (result.exitCode !== 0) {
 47→      throw new ReplicantError(
 48→        ErrorCode.PACKAGE_NOT_FOUND,
 49→        `Failed to launch ${packageName}`,
 50→        "Check the package name and ensure the app is installed"
 51→      );
 52→    }
 53→  }
 54→
 55→  async stop(deviceId: string, packageName: string): Promise<void> {
 56→    await this.adb(["-s", deviceId, "shell", "am", "force-stop", packageName]);
 57→  }
 58→
 59→  async clearData(deviceId: string, packageName: string): Promise<void> {
 60→    await this.adb(["-s", deviceId, "shell", "pm", "clear", packageName]);
 61→  }
 62→
 63→  async shell(deviceId: string, command: string, timeoutMs?: number): Promise<RunResult> {
 64→    return this.adb(["-s", deviceId, "shell", command], timeoutMs);
 65→  }
 66→
 67→  async pull(deviceId: string, remotePath: string, localPath: string): Promise<void> {
 68→    const result = await this.adb(["-s", deviceId, "pull", remotePath, localPath]);
 69→    if (result.exitCode !== 0) {
 70→      throw new ReplicantError(
 71→        ErrorCode.PULL_FAILED,
 72→        `Failed to pull ${remotePath} to ${localPath}`,
 73→        result.stderr || "Check device connection and file paths"
 74→      );
 75→    }
 76→  }
 77→
 78→  async logcat(
 79→    deviceId: string,
 80→    options: { lines?: number; filter?: string; since?: string; package?: string }
 81→  ): Promise<string> {
 82→    const args = ["-s", deviceId, "logcat", "-d"];
 83→
 84→    if (options.since) {
 85→      args.push("-T", options.since);
 86→    }
 87→
 88→    if (options.lines) {
 89→      args.push("-t", options.lines.toString());
 90→    }
 91→
 92→    if (options.filter) {
 93→      args.push(...options.filter.split(" "));
 94→    }
 95→
 96→    const result = await this.adb(args);
 97→    let output = result.stdout;
 98→
 99→    // Package filtering: filter output lines containing the package name
100→    // We use string matching on output lines rather than --pid (requires pidof)
101→    // or -e regex (varies across adb versions)
102→    if (options.package) {
103→      const lines = output.split("\n");
104→      output = lines.filter((line) => line.includes(options.package!)).join("\n");
105→    }
106→
107→    return output;
108→  }
109→
110→  async waitForDevice(deviceId: string, timeoutMs = 30000): Promise<void> {
111→    await this.adb(["-s", deviceId, "wait-for-device"], timeoutMs);
112→  }
113→
114→  async getProperties(deviceId: string): Promise<Record<string, string>> {
115→    const result = await this.adb(["-s", deviceId, "shell", "getprop"]);
116→    const props: Record<string, string> = {};
117→
118→    const regex = /\[([^\]]+)\]:\s*\[([^\]]*)\]/g;
119→    let match;
120→    while ((match = regex.exec(result.stdout)) !== null) {
121→      props[match[1]] = match[2];
122→    }
123→
124→    return props;
125→  }
126→
127→  private async adb(args: string[], timeoutMs?: number): Promise<RunResult> {
128→    return this.runner.runAdb(args, { timeoutMs });
129→  }
130→}
