 12→
 13→  async list(): Promise<EmulatorListResult> {
 14→    const [avdResult, runningResult] = await Promise.all([
 15→      this.runner.runAvdManager(["list", "avd"]),
 16→      this.runner.runEmulator(["-list-avds"]),
 17→    ]);
 18→
 19→    return {
 20→      available: parseAvdList(avdResult.stdout),
 21→      running: parseEmulatorList(runningResult.stdout),
 22→    };
 23→  }
 24→
 25→  async create(
 26→    name: string,
 27→    device: string,
 28→    systemImage: string
 29→  ): Promise<void> {
 30→    const result = await this.runner.runAvdManager([
 31→      "create", "avd",
 32→      "-n", name,
 33→      "-k", systemImage,
 34→      "-d", device,
 35→      "--force",
 36→    ], { timeoutMs: 60000 });
 37→
 38→    if (result.exitCode !== 0) {
 39→      throw new ReplicantError(
 40→        ErrorCode.EMULATOR_START_FAILED,
 41→        `Failed to create AVD: ${result.stderr}`,
 42→        "Check device and system image names"
 43→      );
 44→    }
 45→  }
