 47→  async start(avdName: string): Promise<string> {
 48→    // Start emulator in background - don't wait for it
 49→    // Returns immediately, emulator boots in background
 50→    this.runner.runEmulator([
 51→      "-avd", avdName,
 52→      "-no-snapshot-load",
 53→      "-no-boot-anim",
 54→    ], { timeoutMs: 5000 }).catch(() => {
 55→      // Expected to "timeout" as emulator runs forever
 56→    });
 57→
 58→    // Give it a moment to register
 59→    await new Promise((r) => setTimeout(r, 2000));
 60→
 61→    // Find the new emulator ID
 62→    const result = await this.runner.runAdb(["devices"]);
 63→    const match = result.stdout.match(/emulator-\d+/);
 64→
 65→    if (!match) {
 66→      throw new ReplicantError(
 67→        ErrorCode.EMULATOR_START_FAILED,
 68→        `Emulator ${avdName} failed to start`,
 69→        "Check the AVD name and try again"
