 23→
 24→  async build(
 25→    operation: "assembleDebug" | "assembleRelease" | "bundle",
 26→    module?: string,
 27→    flavor?: string
 28→  ): Promise<{ result: BuildResult; fullOutput: string }> {
 29→    const task = module ? `${module}:${operation}` : operation;
