 40→      throw new ReplicantError(
 41→        ErrorCode.BUILD_FAILED,
 42→        `Build failed: ${parsed.failedTask || "unknown error"}`,
 43→        "Check gradle-get-details for full error output",
 44→        { buildResult: { ...parsed } }
 45→      );
 46→    }
 47→
 48→    return { result: parsed, fullOutput: result.stdout + result.stderr };
 49→  }
 50→
 51→  async test(
 52→    operation: "unitTest" | "connectedTest",
 53→    module?: string,
 54→    filter?: string
 55→  ): Promise<{ result: TestResult; fullOutput: string }> {
 56→    const taskName = operation === "unitTest" ? "testDebugUnitTest" : "connectedDebugAndroidTest";
 57→    const task = module ? `${module}:${taskName}` : taskName;
 58→    const args = [task];
 59→
 60→    if (filter) {
 61→      args.push("--tests", filter);
 62→    }
 63→
 64→    const result = await this.gradle(args, 600000); // 10 min timeout for tests
 65→    const parsed = parseTestOutput(result.stdout + result.stderr);
 66→
 67→    return { result: parsed, fullOutput: result.stdout + result.stderr };
 68→  }
