 70→  async listModules(): Promise<string[]> {
 71→    const result = await this.gradle(["projects"]);
 72→    return parseModuleList(result.stdout);
 73→  }
 74→
 75→  async listVariants(module?: string): Promise<VariantInfo[]> {
 76→    // Try to get variants - this varies by project setup
 77→    const task = module ? `${module}:printVariants` : "printVariants";
 78→    try {
 79→      const result = await this.gradle([task]);
 80→      return parseVariantList(result.stdout);
 81→    } catch {
 82→      // Fallback: return common defaults
 83→      return [
 84→        { name: "debug", buildType: "debug", flavors: [] },
 85→        { name: "release", buildType: "release", flavors: [] },
 86→      ];
 87→    }
 88→  }
