 90→  async listTasks(module?: string): Promise<string[]> {
 91→    const args = module ? [`${module}:tasks`, "--all"] : ["tasks", "--all"];
 92→    const result = await this.gradle(args);
 93→    return parseTaskList(result.stdout);
 94→  }
