 46→/**
 47→ * Tracks the current scaling state between device and image coordinates.
 48→ * Updated on every screenshot operation.
 49→ */
 50→export interface ScalingState {
 51→  scaleFactor: number;
 52→  deviceWidth: number;
 53→  deviceHeight: number;
 54→  imageWidth: number;
 55→  imageHeight: number;
 56→}
 57→
 58→export class UiAutomatorAdapter {
 59→  private scalingState: ScalingState | null = null;
 60→
 61→  constructor(private adb: AdbAdapter = new AdbAdapter()) {}
 62→
 63→  // Getter for tests
 64→  getScalingState(): ScalingState | null {
 65→    return this.scalingState;
 66→  }
 67→
 68→  /**
 69→   * Transforms accessibility tree nodes from device space to image space.
 70→   * This ensures bounds/coordinates match the scaled screenshot when scaling is active.
 71→   */
 72→  private transformTreeToImageSpace(nodes: AccessibilityNode[]): AccessibilityNode[] {
 73→    if (!this.scalingState || this.scalingState.scaleFactor === 1.0) {
 74→      return nodes;
 75→    }
 76→    const sf = this.scalingState.scaleFactor;
 77→    return nodes.map((node) => {
 78→      const newBounds = boundsToImageSpace(node.bounds, sf);
 79→      const center = toImageSpace(node.centerX, node.centerY, sf);
 80→      return {
 81→        ...node,
 82→        bounds: newBounds,
 83→        centerX: center.x,
 84→        centerY: center.y,
 85→        children: node.children ? this.transformTreeToImageSpace(node.children) : [],
 86→      };
 87→    });
 88→  }
 89→
 90→  async dump(deviceId: string): Promise<AccessibilityNode[]> {
 91→    // Dump UI hierarchy to device
 92→    await this.adb.shell(deviceId, "uiautomator dump /sdcard/ui-dump.xml");
 93→
 94→    // Pull the dump
 95→    const result = await this.adb.shell(deviceId, "cat /sdcard/ui-dump.xml");
 96→
 97→    // Clean up
 98→    await this.adb.shell(deviceId, "rm /sdcard/ui-dump.xml");
 99→
100→    const tree = parseUiDump(result.stdout);
101→    return this.transformTreeToImageSpace(tree);
102→  }
103→
104→  async find(
105→    deviceId: string,
106→    selector: {
107→      resourceId?: string;
108→      text?: string;
109→      textContains?: string;
110→      className?: string;
111→    }
112→  ): Promise<AccessibilityNode[]> {
113→    const tree = await this.dump(deviceId);
114→    return findElements(tree, selector);
115→  }
