117→  async tap(deviceId: string, x: number, y: number, deviceSpace?: boolean): Promise<void> {
118→    // Convert from image space to device space if scaling is active
119→    // Skip conversion if deviceSpace=true (coordinates are already in device space)
120→    let tapX = x;
121→    let tapY = y;
122→    if (!deviceSpace && this.scalingState && this.scalingState.scaleFactor !== 1.0) {
123→      const converted = toDeviceSpace(x, y, this.scalingState.scaleFactor);
124→      tapX = converted.x;
125→      tapY = converted.y;
126→    }
127→    await this.adb.shell(deviceId, `input tap ${tapX} ${tapY}`);
128→  }
129→
130→  async tapElement(deviceId: string, element: AccessibilityNode): Promise<void> {
131→    await this.tap(deviceId, element.centerX, element.centerY);
132→  }
133→
134→  async input(deviceId: string, text: string): Promise<void> {
135→    // Escape special characters for shell
136→    const escaped = text.replace(/(['"\\$`])/g, "\\$1").replace(/ /g, "%s");
137→    await this.adb.shell(deviceId, `input text "${escaped}"`);
138→  }
139→
140→  async scroll(
141→    deviceId: string,
142→    direction: "up" | "down" | "left" | "right",
143→    amount: number = 0.5
144→  ): Promise<void> {
145→    const screen = await this.getScreenMetadata(deviceId);
146→    const { width, height } = screen;
147→
148→    // Calculate scroll distance based on amount (0-1 representing screen percentage)
149→    const scrollDistance = Math.round(
150→      (direction === "up" || direction === "down" ? height : width) * amount * 0.8
151→    );
152→
153→    // Center point of the screen
154→    const centerX = Math.round(width / 2);
155→    const centerY = Math.round(height / 2);
156→
157→    // Calculate start and end points based on direction
158→    // Note: "scroll down" means content moves up, so we swipe up (finger moves from bottom to top)
159→    let startX: number, startY: number, endX: number, endY: number;
160→    switch (direction) {
161→      case "down": // Scroll down = swipe up = finger moves up
162→        startX = centerX;
163→        startY = centerY + scrollDistance / 2;
164→        endX = centerX;
165→        endY = centerY - scrollDistance / 2;
166→        break;
167→      case "up": // Scroll up = swipe down = finger moves down
168→        startX = centerX;
169→        startY = centerY - scrollDistance / 2;
170→        endX = centerX;
171→        endY = centerY + scrollDistance / 2;
172→        break;
173→      case "right": // Scroll right = swipe left = finger moves left
174→        startX = centerX + scrollDistance / 2;
175→        startY = centerY;
176→        endX = centerX - scrollDistance / 2;
177→        endY = centerY;
178→        break;
179→      case "left": // Scroll left = swipe right = finger moves right
180→        startX = centerX - scrollDistance / 2;
181→        startY = centerY;
182→        endX = centerX + scrollDistance / 2;
183→        endY = centerY;
184→        break;
185→    }
186→
187→    // Duration in ms - longer for larger scrolls, minimum 100ms
188→    const duration = Math.max(100, Math.round(scrollDistance / 2));
189→    await this.adb.shell(deviceId, `input swipe ${startX} ${startY} ${endX} ${endY} ${duration}`);
190→  }
191→
192→  async screenshot(deviceId: string, options: ScreenshotOptions = {}): Promise<ScreenshotResult> {
193→    const remotePath = "/sdcard/replicant-screenshot.png";
194→    const maxDimension = options.maxDimension ?? 800;
195→
196→    // Capture screenshot on device
197→    const captureResult = await this.adb.shell(deviceId, `screencap -p ${remotePath}`);
198→    if (captureResult.exitCode !== 0) {
199→      throw new ReplicantError(
200→        ErrorCode.SCREENSHOT_FAILED,
201→        "Failed to capture screenshot",
202→        captureResult.stderr || "Ensure device screen is on and unlocked"
203→      );
204→    }
205→
206→    try {
207→      if (options.inline) {
208→        // Inline mode: pull to temp, scale, convert to JPEG, return base64
209→        const tempPath = path.join(os.tmpdir(), `replicant-inline-${Date.now()}.png`);
210→
211→        try {
212→          // Pull to temp file
213→          await this.adb.pull(deviceId, remotePath, tempPath);
214→
215→          // Get dimensions
216→          const metadata = await sharp(tempPath).metadata();
217→          const deviceWidth = metadata.width!;
218→          const deviceHeight = metadata.height!;
219→
220→          // Calculate scale factor
221→          const scaleFactor = calculateScaleFactor(deviceWidth, deviceHeight, maxDimension);
222→          const imageWidth = Math.round(deviceWidth / scaleFactor);
223→          const imageHeight = Math.round(deviceHeight / scaleFactor);
224→
225→          // Sharpen, scale, convert to WebP, strip ICC profile
226→          const buffer = await sharp(tempPath)
227→            .sharpen({ sigma: 0.5 })
228→            .resize(imageWidth, imageHeight)
229→            .webp({ quality: 72, effort: 5, smartSubsample: true })
230→            .withMetadata({})
231→            .toBuffer();
232→
233→          // Update scaling state (now supported for inline!)
234→          this.scalingState = {
235→            scaleFactor,
236→            deviceWidth,
237→            deviceHeight,
238→            imageWidth,
239→            imageHeight,
240→          };
241→
242→          return {
243→            mode: "inline",
244→            base64: buffer.toString("base64"),
245→            mimeType: "image/webp",
246→            sizeBytes: buffer.length,
247→            device: { width: deviceWidth, height: deviceHeight },
248→            image: { width: imageWidth, height: imageHeight },
249→            scaleFactor,
250→          };
251→        } finally {
252→          // Clean up temp file
253→          const fsPromises = await import("fs/promises");
254→          await fsPromises.unlink(tempPath).catch(() => {});
255→        }
256→      } else {
257→        // File mode: pull to local, then optionally scale
258→        const localPath = options.localPath || getDefaultScreenshotPath();
259→        await this.adb.pull(deviceId, remotePath, localPath);
260→
261→        // Get image dimensions
262→        const metadata = await sharp(localPath).metadata();
263→        const deviceWidth = metadata.width!;
264→        const deviceHeight = metadata.height!;
265→
266→        // Handle raw mode
267→        if (options.raw) {
268→          this.scalingState = {
269→            scaleFactor: 1.0,
270→            deviceWidth,
271→            deviceHeight,
272→            imageWidth: deviceWidth,
273→            imageHeight: deviceHeight,
274→          };
275→          return {
276→            mode: "file",
277→            path: localPath,
278→            device: { width: deviceWidth, height: deviceHeight },
279→            image: { width: deviceWidth, height: deviceHeight },
280→            scaleFactor: 1.0,
281→            warning: "Raw mode: no scaling applied. May exceed API limits with multiple images.",
282→          };
283→        }
284→
285→        // Calculate scale factor
286→        const scaleFactor = calculateScaleFactor(deviceWidth, deviceHeight, maxDimension);
287→
288→        if (scaleFactor === 1.0) {
289→          // No scaling needed
290→          this.scalingState = {
291→            scaleFactor: 1.0,
292→            deviceWidth,
293→            deviceHeight,
294→            imageWidth: deviceWidth,
295→            imageHeight: deviceHeight,
296→          };
297→          return {
298→            mode: "file",
299→            path: localPath,
300→            device: { width: deviceWidth, height: deviceHeight },
301→            image: { width: deviceWidth, height: deviceHeight },
302→            scaleFactor: 1.0,
303→          };
304→        }
305→
306→        // Scale the image
307→        const imageWidth = Math.round(deviceWidth / scaleFactor);
308→        const imageHeight = Math.round(deviceHeight / scaleFactor);
309→
310→        await sharp(localPath)
311→          .resize(imageWidth, imageHeight)
312→          .toFile(localPath + ".tmp");
313→
314→        // Replace original with scaled version
315→        const fsPromises = await import("fs/promises");
316→        await fsPromises.rename(localPath + ".tmp", localPath);
317→
318→        // Update scaling state
319→        this.scalingState = {
320→          scaleFactor,
321→          deviceWidth,
322→          deviceHeight,
323→          imageWidth,
324→          imageHeight,
325→        };
326→
327→        return {
328→          mode: "file",
329→          path: localPath,
330→          device: { width: deviceWidth, height: deviceHeight },
331→          image: { width: imageWidth, height: imageHeight },
332→          scaleFactor,
333→        };
334→      }
335→    } finally {
336→      // Always clean up remote file
337→      await this.adb.shell(deviceId, `rm -f ${remotePath}`);
338→    }
339→  }
