341→  async accessibilityCheck(deviceId: string): Promise<{
342→    hasAccessibleElements: boolean;
343→    clickableCount: number;
344→    textCount: number;
345→    totalElements: number;
346→  }> {
347→    const tree = await this.dump(deviceId);
348→    const flat = flattenTree(tree);
349→
350→    const clickableCount = flat.filter((n) => n.clickable).length;
351→    const textCount = flat.filter((n) => n.text || n.contentDesc).length;
352→
353→    return {
354→      hasAccessibleElements: textCount > 0,
355→      clickableCount,
356→      textCount,
357→      totalElements: flat.length,
358→    };
359→  }
