 26→async function handleList(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 27→  const result = await context.emulator.list();
 28→  return { available: result.available, running: result.running };
 29→}
 30→
 31→async function handleCreate(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 32→  if (!input.avdName || !input.device || !input.systemImage) {
 33→    throw new ReplicantError(
 34→      ErrorCode.INPUT_VALIDATION_FAILED,
 35→      "avdName, device, and systemImage are required for create",
 36→      "Provide all three parameters: avdName, device, and systemImage",
 37→    );
 38→  }
 39→  await context.emulator.create(input.avdName, input.device, input.systemImage);
 40→  return { created: input.avdName };
 41→}
 42→
 43→async function handleStart(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 44→  if (!input.avdName) {
 45→    throw new ReplicantError(
 46→      ErrorCode.INPUT_VALIDATION_FAILED,
 47→      "avdName is required for start",
 48→      "Provide the AVD name to start",
 49→    );
 50→  }
 51→  const emulatorId = await context.emulator.start(input.avdName);
 52→
 53→  const devices = await context.adb.getDevices();
 54→  const device = devices.find((d) => d.id === emulatorId);
 55→  if (device) {
 56→    context.deviceState.setCurrentDevice(device);
 57→  }
 58→
 59→  return { started: input.avdName, emulatorId, autoSelected: true };
 60→}
 61→
 62→async function handleKill(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 63→  const emulatorId = input.emulatorId || context.deviceState.getCurrentDevice()?.id;
 64→  if (!emulatorId) {
 65→    throw new ReplicantError(
 66→      ErrorCode.INPUT_VALIDATION_FAILED,
 67→      "emulatorId is required or select an emulator first",
 68→      "Use emulator-device list to see running emulators, or provide emulatorId",
 69→    );
 70→  }
 71→  await context.emulator.kill(emulatorId);
 72→
 73→  if (context.deviceState.getCurrentDevice()?.id === emulatorId) {
 74→    context.deviceState.clearCurrentDevice();
 75→  }
 76→
 77→  return { killed: emulatorId };
 78→}
 79→
 80→async function handleWipe(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 81→  if (!input.avdName) {
 82→    throw new ReplicantError(
 83→      ErrorCode.INPUT_VALIDATION_FAILED,
 84→      "avdName is required for wipe",
 85→      "Provide the AVD name to wipe",
 86→    );
 87→  }
 88→  await context.emulator.wipe(input.avdName);
 89→  return { wiped: input.avdName };
 90→}
 91→
 92→function resolveEmulatorId(input: EmulatorDeviceInput, context: ServerContext): string {
 93→  const emulatorId = input.emulatorId || context.deviceState.getCurrentDevice()?.id;
 94→  if (!emulatorId) {
 95→    throw new ReplicantError(
 96→      ErrorCode.INPUT_VALIDATION_FAILED,
 97→      `emulatorId is required for ${input.operation}`,
 98→      "Use emulator-device list to see running emulators, or provide emulatorId",
 99→    );
100→  }
101→  return emulatorId;
102→}
103→
104→async function handleSnapshotSave(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
105→  const emulatorId = resolveEmulatorId(input, context);
106→  if (!input.snapshotName) {
107→    throw new ReplicantError(
108→      ErrorCode.INPUT_VALIDATION_FAILED,
109→      "snapshotName is required for snapshot-save",
110→      "Provide the snapshot name to save",
