112→  }
113→  await context.emulator.snapshotSave(emulatorId, input.snapshotName);
114→  return { saved: input.snapshotName, emulatorId };
115→}
116→
117→async function handleSnapshotLoad(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
118→  const emulatorId = resolveEmulatorId(input, context);
119→  if (!input.snapshotName) {
120→    throw new ReplicantError(
121→      ErrorCode.INPUT_VALIDATION_FAILED,
122→      "snapshotName is required for snapshot-load",
123→      "Provide the snapshot name to load",
124→    );
125→  }
126→  await context.emulator.snapshotLoad(emulatorId, input.snapshotName);
127→  return { loaded: input.snapshotName, emulatorId };
128→}
129→
130→async function handleSnapshotList(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
131→  const emulatorId = resolveEmulatorId(input, context);
132→  const snapshots = await context.emulator.snapshotList(emulatorId);
133→  return { snapshots, emulatorId };
134→}
135→
136→async function handleSnapshotDelete(input: EmulatorDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
137→  const emulatorId = resolveEmulatorId(input, context);
138→  if (!input.snapshotName) {
139→    throw new ReplicantError(
140→      ErrorCode.INPUT_VALIDATION_FAILED,
141→      "snapshotName is required for snapshot-delete",
