  5→export const gradleGetDetailsInputSchema = z.object({
  6→  id: z.string(),
  7→  detailType: z.enum(["logs", "errors", "tasks", "all"]).optional().default("all"),
  8→  maxChars: z.number().min(1).optional(),
  9→  summaryOnly: z.boolean().optional(),
 10→  previewChars: z.number().min(1).optional(),
 11→});
