 13→export type GradleGetDetailsInput = z.infer<typeof gradleGetDetailsInputSchema>;
 14→
 15→type GradleDetailsCacheEntry = {
 16→  fullOutput: string;
 17→  result: Record<string, unknown>;
 18→  operation: string;
 19→};
 20→
 21→type TruncateResult = { text: string; truncated: boolean; originalChars: number };
 22→
 23→function truncateText(text: string, maxChars?: number): TruncateResult {
 24→  if (!maxChars || text.length <= maxChars) {
 25→    return { text, truncated: false, originalChars: text.length };
 26→  }
 27→
 28→  return {
 29→    text: text.slice(0, maxChars),
 30→    truncated: true,
 31→    originalChars: text.length,
 32→  };
 33→}
 34→
 35→function summaryFromText(text: string): { lineCount: number; warnCount: number; errorCount: number; charCount: number } {
 36→  return {
 37→    lineCount: text.split("\n").filter(Boolean).length,
 38→    warnCount: (text.match(/^w:|\bwarning:\b|\bWARNING:\b/gm) || []).length,
 39→    errorCount: (text.match(/^e:|\berror:\b|\bError:\b|\bFAILED\b/gm) || []).length,
 40→    charCount: text.length,
 41→  };
 42→}
 43→
 44→function buildLogsResponse(
 45→  input: GradleGetDetailsInput,
 46→  fullOutput: string,
 47→  operation: string,
 48→  previewChars: number,
 49→): Record<string, unknown> {
 50→  if (input.summaryOnly) {
 51→    return {
 52→      id: input.id,
 53→      detailType: "logs",
 54→      operation,
 55→      summarized: true,
 56→      summary: summaryFromText(fullOutput),
 57→      preview: fullOutput.slice(0, previewChars),
 58→    };
 59→  }
 60→
 61→  const truncated = truncateText(fullOutput, input.maxChars);
 62→  return {
 63→    id: input.id,
 64→    detailType: "logs",
 65→    operation,
 66→    logs: truncated.text,
 67→    truncated: truncated.truncated,
 68→    originalChars: truncated.originalChars,
 69→  };
 70→}
 71→
 72→function buildErrorsResponse(
 73→  input: GradleGetDetailsInput,
 74→  fullOutput: string,
 75→  operation: string,
 76→): Record<string, unknown> {
 77→  const errorLines = fullOutput.split("\n").filter(
 78→    (line) =>
 79→      line.includes("error:") ||
 80→      line.includes("Error:") ||
 81→      line.includes("FAILED") ||
 82→      line.startsWith("e:"),
 83→  );
 84→  const truncated = truncateText(errorLines.join("\n"), input.maxChars);
 85→
 86→  return {
 87→    id: input.id,
 88→    detailType: "errors",
 89→    operation,
 90→    errors: truncated.text,
 91→    truncated: truncated.truncated,
 92→    originalChars: truncated.originalChars,
 93→    errorCount: errorLines.length,
 94→  };
 95→}
 96→
 97→function buildTasksResponse(
 98→  input: GradleGetDetailsInput,
 99→  fullOutput: string,
100→  operation: string,
101→): Record<string, unknown> {
102→  const taskLines = fullOutput.split("\n").filter((line) => line.startsWith("> Task"));
103→
104→  if (input.summaryOnly) {
105→    return {
106→      id: input.id,
107→      detailType: "tasks",
108→      operation,
109→      summarized: true,
110→      taskCount: taskLines.length,
111→      tasksPreview: taskLines.slice(0, 10),
112→    };
113→  }
114→
115→  return {
116→    id: input.id,
117→    detailType: "tasks",
118→    operation,
119→    tasks: taskLines
120→      .map((line) => {
121→        const match = line.match(/> Task (:\S+)(?:\s+(.+))?/);
122→        return match ? { task: match[1], status: match[2] || "executed" } : null;
123→      })
124→      .filter(Boolean),
125→  };
126→}
