128→function buildAllResponse(
129→  input: GradleGetDetailsInput,
130→  fullOutput: string,
131→  result: Record<string, unknown>,
132→  operation: string,
133→  previewChars: number,
134→): Record<string, unknown> {
135→  if (input.summaryOnly) {
136→    return {
137→      id: input.id,
138→      detailType: "all",
139→      operation,
140→      summarized: true,
141→      summary: {
142→        ...summaryFromText(fullOutput),
143→        resultKeys: Object.keys(result),
144→      },
145→      preview: fullOutput.slice(0, previewChars),
146→    };
147→  }
148→
149→  const truncated = truncateText(fullOutput, input.maxChars);
150→  return {
151→    id: input.id,
152→    detailType: "all",
153→    operation,
154→    result,
155→    fullOutput: truncated.text,
156→    truncated: truncated.truncated,
157→    originalChars: truncated.originalChars,
158→  };
159→}
160→
161→function getCacheEntry(input: GradleGetDetailsInput, context: ServerContext): GradleDetailsCacheEntry {
162→  const entry = context.cache.get<GradleDetailsCacheEntry>(input.id);
163→
164→  if (!entry) {
165→    throw new ReplicantError(
166→      ErrorCode.CACHE_MISS,
167→      `No cached data found for id: ${input.id}`,
168→      "The cache entry may have expired. Re-run the build/test operation.",
169→    );
170→  }
171→
172→  return entry.data;
173→}
174→
175→export async function handleGradleGetDetailsTool(
176→  input: GradleGetDetailsInput,
177→  context: ServerContext
178→): Promise<Record<string, unknown>> {
179→  const { fullOutput, result, operation } = getCacheEntry(input, context);
180→  const previewChars = input.previewChars ?? 400;
181→
182→  switch (input.detailType) {
183→    case "logs":
184→      return buildLogsResponse(input, fullOutput, operation, previewChars);
185→    case "errors":
186→      return buildErrorsResponse(input, fullOutput, operation);
187→    case "tasks":
188→      return buildTasksResponse(input, fullOutput, operation);
189→
190→    case "all":
191→    default:
192→      return buildAllResponse(input, fullOutput, result, operation, previewChars);
193→  }
194→}
