 22→/**
 23→ * Convert gradle TestResult into BaselineTestResult[] for baseline storage/comparison.
 24→ * Captures both passed and failed test names for accurate regression detection.
 25→ */
 26→export function convertToBaselineResults(result: TestResult): BaselineTestResult[] {
 27→  const results: BaselineTestResult[] = [];
 28→
 29→  for (const testName of result.passedTests) {
 30→    results.push({ test: testName, status: "pass" });
 31→  }
 32→
 33→  for (const failure of result.failures) {
 34→    results.push({ test: failure.test, status: "fail" });
 35→  }
 36→
 37→  return results;
 38→}
