16→export async function handleRtfmTool(input: RtfmInput): Promise<{ content: string }> {
17→  if (!input.category && !input.tool) {
18→    // Return index
19→    const content = await readFile(join(RTFM_DIR, "index.md"), "utf-8");
20→    return { content };
21→  }
22→
23→  if (input.category) {
24→    try {
25→      const content = await readFile(join(RTFM_DIR, `${input.category}.md`), "utf-8");
26→      return { content };
27→    } catch {
28→      return { content: `Category '${input.category}' not found. Available: build, adb, emulator, ui, cache` };
29→    }
30→  }
31→
32→  if (input.tool) {
33→    // Map tool to category
34→    const toolToCategory: Record<string, string> = {
35→      "gradle-build": "build",
36→      "gradle-test": "build",
37→      "gradle-list": "build",
38→      "gradle-get-details": "build",
39→      "adb-device": "adb",
40→      "adb-app": "adb",
41→      "adb-logcat": "adb",
42→      "adb-shell": "adb",
43→      "emulator-device": "emulator",
44→      "ui": "ui",
45→      "cache": "cache",
46→      "rtfm": "index",
47→    };
48→
49→    const category = toolToCategory[input.tool] || "index";
50→    try {
51→      const content = await readFile(join(RTFM_DIR, `${category}.md`), "utf-8");
52→
53→      // Try to extract just the relevant section
54→      const toolSection = extractToolSection(content, input.tool);
55→      return { content: toolSection || content };
56→    } catch {
57→      return { content: `Tool '${input.tool}' not found.` };
58→    }
59→  }
60→
61→  return { content: "No documentation found." };
62→}
63→
64→function extractToolSection(content: string, toolName: string): string | null {
65→  const regex = new RegExp(`## ${toolName}[\\s\\S]*?(?=## |$)`, "i");
66→  const match = content.match(regex);
67→  return match ? match[0].trim() : null;
68→}
