  1→import { CacheEntry, CacheConfig, DEFAULT_CACHE_CONFIG } from "../types/index.js";
  2→import { randomBytes } from "crypto";
  3→
  4→export interface CacheStats {
  5→  entryCount: number;
  6→  totalSizeBytes: number;
  7→  typeBreakdown: Record<string, number>;
  8→  config: CacheConfig;
  9→}
 10→
 11→export class CacheManager {
 12→  private cache = new Map<string, CacheEntry>();
 13→  private accessOrder: string[] = [];
 14→  private config: CacheConfig;
 15→
 16→  constructor(config: Partial<CacheConfig> = {}) {
 17→    this.config = { ...DEFAULT_CACHE_CONFIG, ...config };
 18→  }
 19→
 20→  generateId(type: string): string {
 21→    const hash = randomBytes(4).toString("hex");
 22→    const timestamp = Date.now();
 23→    return `${type}-${hash}-${timestamp}`;
 24→  }
 25→
 26→  set<T>(id: string, data: T, type: string, ttlMs?: number): void {
 27→    const now = Date.now();
 28→    const sizeBytes = JSON.stringify(data).length;
 29→
 30→    // LRU eviction
 31→    while (this.cache.size >= this.config.maxEntries) {
 32→      const oldest = this.accessOrder.shift();
 33→      if (oldest) {
 34→        this.cache.delete(oldest);
 35→      }
 36→    }
 37→
 38→    const entry: CacheEntry<T> = {
 39→      data,
 40→      expiresAt: now + (ttlMs ?? this.config.defaultTtlMs),
 41→      metadata: {
 42→        createdAt: now,
 43→        type,
 44→        sizeBytes,
 45→      },
 46→    };
 47→
 48→    this.cache.set(id, entry);
 49→    this.accessOrder.push(id);
 50→  }
 51→
 52→  get<T>(id: string): CacheEntry<T> | undefined {
 53→    const entry = this.cache.get(id) as CacheEntry<T> | undefined;
 54→
 55→    if (!entry) {
 56→      return undefined;
 57→    }
 58→
 59→    // Check expiration
 60→    if (Date.now() > entry.expiresAt) {
 61→      this.cache.delete(id);
 62→      this.accessOrder = this.accessOrder.filter((k) => k !== id);
 63→      return undefined;
 64→    }
 65→
 66→    // Update access order for LRU
 67→    this.accessOrder = this.accessOrder.filter((k) => k !== id);
 68→    this.accessOrder.push(id);
 69→
 70→    return entry;
 71→  }
 72→
 73→  clear(id: string): void {
 74→    this.cache.delete(id);
 75→    this.accessOrder = this.accessOrder.filter((k) => k !== id);
 76→  }
 77→
 78→  clearAll(): void {
 79→    this.cache.clear();
 80→    this.accessOrder = [];
 81→  }
 82→
 83→  invalidateByType(type: string): void {
 84→    for (const [id, entry] of this.cache.entries()) {
 85→      if (entry.metadata.type === type) {
 86→        this.cache.delete(id);
 87→      }
 88→    }
 89→    this.accessOrder = this.accessOrder.filter((id) => this.cache.has(id));
 90→  }
 91→
 92→  getStats(): CacheStats {
 93→    const typeBreakdown: Record<string, number> = {};
 94→    let totalSizeBytes = 0;
 95→
 96→    for (const entry of this.cache.values()) {
 97→      const type = entry.metadata.type;
 98→      typeBreakdown[type] = (typeBreakdown[type] ?? 0) + 1;
 99→      totalSizeBytes += entry.metadata.sizeBytes ?? 0;
100→    }
101→
102→    return {
103→      entryCount: this.cache.size,
104→      totalSizeBytes,
105→      typeBreakdown,
106→      config: this.config,
107→    };
108→  }
109→
110→  getConfig(): CacheConfig {
111→    return { ...this.config };
112→  }
113→
114→  setConfig(config: Partial<CacheConfig>): void {
115→    this.config = { ...this.config, ...config };
116→  }
117→}
