  1→import { ServerContext } from "../server.js";
  2→import { OcrElement, UiConfig, ReplicantError, ErrorCode } from "../types/index.js";
  3→import { AccessibilityNode, flattenTree } from "../parsers/ui-dump.js";
  4→import {
  5→  FindElement,
  6→  FindOptions,
  7→  FindTier,
  8→  FindWithFallbacksResult,
  9→  GridElement,
 10→} from "../types/icon-recognition.js";
 11→import { UiInput } from "./ui.js";
 12→
 13→// Type guards for different element types
 14→export function isAccessibilityNode(el: FindElement): el is AccessibilityNode {
 15→  return "centerX" in el && "className" in el;
 16→}
 17→
 18→export function isOcrElement(el: FindElement): el is OcrElement {
 19→  return "confidence" in el && "center" in el;
 20→}
 21→
 22→export function isGridElement(el: FindElement): el is GridElement {
 23→  return "center" in el && "bounds" in el && !("confidence" in el) && !("centerX" in el);
 24→}
 25→
 26→export function getElementCenter(element: FindElement): { x: number; y: number } {
 27→  if (isAccessibilityNode(element)) {
 28→    return { x: element.centerX, y: element.centerY };
 29→  }
 30→  return element.center;
 31→}
 32→
 33→function calculateDistance(p1: { x: number; y: number }, p2: { x: number; y: number }): number {
 34→  return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
 35→}
 36→
 37→function isPointInBounds(
 38→  point: { x: number; y: number },
 39→  bounds: { left: number; top: number; right: number; bottom: number }
 40→): boolean {
 41→  return (
 42→    point.x >= bounds.left &&
 43→    point.x <= bounds.right &&
 44→    point.y >= bounds.top &&
 45→    point.y <= bounds.bottom
 46→  );
 47→}
 48→
 49→function boundsArea(bounds: { left: number; top: number; right: number; bottom: number }): number {
 50→  return (bounds.right - bounds.left) * (bounds.bottom - bounds.top);
 51→}
 52→
 53→function findContainingSiblingTargets(
 54→  tree: AccessibilityNode[],
 55→  anchorPoint: { x: number; y: number },
 56→  targetElements: AccessibilityNode[]
 57→): AccessibilityNode[] {
 58→  const flat = flattenTree(tree);
 59→  const containingTargets: AccessibilityNode[] = [];
 60→
 61→  for (const target of targetElements) {
 62→    const targetCenter = { x: target.centerX, y: target.centerY };
 63→
 64→    let smallestContainerForTarget: AccessibilityNode | null = null;
 65→    let smallestArea = Infinity;
 66→
 67→    for (const node of flat) {
 68→      if (!node.className?.includes("ViewGroup")) continue;
 69→      if (!isPointInBounds(targetCenter, node.bounds)) continue;
 70→
 71→      const area = boundsArea(node.bounds);
 72→      if (area < smallestArea) {
 73→        smallestArea = area;
 74→        smallestContainerForTarget = node;
 75→      }
 76→    }
 77→
 78→    if (smallestContainerForTarget && isPointInBounds(anchorPoint, smallestContainerForTarget.bounds)) {
 79→      containingTargets.push(target);
 80→    }
 81→  }
 82→
 83→  return containingTargets;
 84→}
 85→
 86→function formatElement(el: FindElement, index: number, debug: boolean): Record<string, unknown> {
 87→  if (isAccessibilityNode(el)) {
 88→    return {
 89→      index,
 90→      text: el.text,
 91→      resourceId: el.resourceId,
 92→      className: el.className,
 93→      centerX: el.centerX,
 94→      centerY: el.centerY,
 95→      bounds: el.bounds,
 96→      clickable: el.clickable,
 97→    };
 98→  } else if (isOcrElement(el)) {
 99→    return {
100→      index,
101→      text: el.text,
102→      center: el.center,
103→      bounds: el.bounds,
104→      confidence: debug ? el.confidence : undefined,
105→    };
106→  }
107→  return { index, center: el.center, bounds: el.bounds };
108→}
109→
110→function sortByProximity(
111→  elements: FindElement[],
112→  anchorCenter: { x: number; y: number },
113→  containingCenters: Set<string> | null
114→): boolean {
115→  if (containingCenters) {
116→    elements.sort((a, b) => {
117→      const aCenter = getElementCenter(a);
118→      const bCenter = getElementCenter(b);
119→      const aContains = containingCenters.has(`${aCenter.x},${aCenter.y}`);
120→      const bContains = containingCenters.has(`${bCenter.x},${bCenter.y}`);
121→
122→      if (aContains && !bContains) return -1;
123→      if (!aContains && bContains) return 1;
124→
125→      return calculateDistance(aCenter, anchorCenter) - calculateDistance(bCenter, anchorCenter);
126→    });
127→    return true;
128→  }
129→
130→  elements.sort((a, b) =>
131→    calculateDistance(getElementCenter(a), anchorCenter) - calculateDistance(getElementCenter(b), anchorCenter)
132→  );
133→  return false;
134→}
135→
136→async function resolveAnchorCenter(
137→  context: ServerContext,
138→  deviceId: string,
139→  nearestTo: string,
140→  maxTier: FindTier | undefined
141→): Promise<{ x: number; y: number } | null> {
142→  const anchorOptions: FindOptions = {
143→    debug: false,
144→    includeVisualFallback: false,
145→  };
146→  if (maxTier !== undefined) {
147→    anchorOptions.maxTier = maxTier;
148→  }
149→
150→  const anchorResult = await context.ui.findWithFallbacks(deviceId, { text: nearestTo }, anchorOptions);
151→  if (anchorResult.elements.length > 0) {
152→    return getElementCenter(anchorResult.elements[0]);
153→  }
154→  return null;
155→}
156→
157→function buildFindOptions(input: UiInput, debug: boolean, config: UiConfig): FindOptions {
158→  const maxTier = input.maxTier as FindTier | undefined;
159→  const options: FindOptions = {
160→    debug,
161→    includeVisualFallback: config.autoFallbackScreenshot,
162→    includeBase64: config.includeBase64,
163→    maxTier,
164→  };
165→
166→  if (input.gridCell !== undefined) {
167→    options.gridCell = input.gridCell;
168→  }
169→  if (input.gridPosition !== undefined) {
170→    options.gridPosition = input.gridPosition as 1 | 2 | 3 | 4 | 5;
171→  }
172→  return options;
173→}
174→
175→function appendResultMetadata(
176→  response: Record<string, unknown>,
177→  result: FindWithFallbacksResult,
178→  debug: boolean
179→): void {
180→  if (result.tier !== undefined) response.tier = result.tier;
181→  if (result.confidence) response.confidence = result.confidence;
182→  if (result.stoppedEarly !== undefined) response.stoppedEarly = result.stoppedEarly;
183→  if (result.stoppedAtTier !== undefined) response.stoppedAtTier = result.stoppedAtTier;
184→  if (result.nextTierAvailable !== undefined) response.nextTierAvailable = result.nextTierAvailable;
185→  if (result.stopReason) response.stopReason = result.stopReason;
186→
187→  if (debug) {
188→    response.source = result.source;
189→    if (result.fallbackReason) response.fallbackReason = result.fallbackReason;
190→  }
191→}
192→
193→function appendFallbackPayload(response: Record<string, unknown>, result: FindWithFallbacksResult): void {
194→  if (result.candidates) {
195→    response.candidates = result.candidates;
196→    if (result.truncated) response.truncated = result.truncated;
197→    if (result.totalCandidates) response.totalCandidates = result.totalCandidates;
198→  }
199→  if (result.gridImage) response.gridImage = result.gridImage;
200→  if (result.gridPositions) response.gridPositions = result.gridPositions;
201→  if (result.visualFallback) response.visualFallback = result.visualFallback;
202→}
203→
204→function appendNearestToMetadata(
205→  response: Record<string, unknown>,
206→  nearestTo: string | undefined,
207→  anchorCenter: { x: number; y: number } | null,
208→  usedContainment: boolean
209→): void {
210→  if (nearestTo && anchorCenter) {
211→    response.sortedByProximityTo = {
212→      query: nearestTo,
213→      anchor: anchorCenter,
214→      method: usedContainment ? "containment" : "distance",
215→    };
216→  } else if (nearestTo && !anchorCenter) {
217→    response.nearestToWarning = `Could not find anchor element: "${nearestTo}"`;
218→  }
219→}
220→
221→export async function handleFind(
222→  input: UiInput,
223→  context: ServerContext,
224→  config: UiConfig,
225→  deviceId: string
226→): Promise<Record<string, unknown>> {
227→  if (!input.selector) {
228→    throw new ReplicantError(
229→      ErrorCode.INPUT_VALIDATION_FAILED,
230→      "selector is required for find operation",
231→      "Provide a selector with text, textContains, resourceId, or className",
232→    );
233→  }
234→
235→  const debug = input.debug ?? false;
236→  const nearestTo = input.selector.nearestTo;
237→
238→  if (input.selector.text || input.selector.textContains) {
239→    return handleTextFind(input, context, config, deviceId, debug, nearestTo);
240→  }
241→
242→  return handleSelectorFind(input, context, config, deviceId);
243→}
244→
245→async function handleTextFind(
246→  input: UiInput,
247→  context: ServerContext,
248→  config: UiConfig,
249→  deviceId: string,
250→  debug: boolean,
251→  nearestTo: string | undefined
252→): Promise<Record<string, unknown>> {
253→  const maxTier = input.maxTier as FindTier | undefined;
254→  const anchorCenter = nearestTo
255→    ? await resolveAnchorCenter(context, deviceId, nearestTo, maxTier)
256→    : null;
257→  const findOptions = buildFindOptions(input, debug, config);
258→
259→  const result = await context.ui.findWithFallbacks(deviceId, input.selector!, findOptions);
260→
261→  let usedContainment = false;
262→  if (anchorCenter && result.elements.length > 0) {
263→    const accessibilityElements = result.elements.filter(isAccessibilityNode);
264→    if (accessibilityElements.length > 0) {
265→      const tree = await context.ui.dump(deviceId);
266→      const containingMatches = findContainingSiblingTargets(tree, anchorCenter, accessibilityElements);
267→
268→      const containingCenters = containingMatches.length > 0
269→        ? new Set(containingMatches.map((el) => `${el.centerX},${el.centerY}`))
270→        : null;
271→      usedContainment = sortByProximity(result.elements, anchorCenter, containingCenters);
272→    }
273→  }
274→
275→  context.lastFindResults = result.elements;
276→
277→  const response: Record<string, unknown> = {
278→    elements: result.elements.map((el, index) => formatElement(el, index, debug)),
279→    count: result.elements.length,
280→    deviceId,
281→  };
282→
283→  appendResultMetadata(response, result, debug);
284→  appendNearestToMetadata(response, nearestTo, anchorCenter, usedContainment);
285→  appendFallbackPayload(response, result);
286→
287→  return response;
288→}
289→
290→async function handleSelectorFind(
291→  input: UiInput,
292→  context: ServerContext,
293→  config: UiConfig,
294→  deviceId: string
295→): Promise<Record<string, unknown>> {
296→  const elements = await context.ui.find(deviceId, input.selector!);
297→  context.lastFindResults = elements;
298→
299→  const response: Record<string, unknown> = {
300→    elements: elements.map((el, index) => ({
301→      index,
302→      text: el.text,
303→      resourceId: el.resourceId,
304→      className: el.className,
305→      centerX: el.centerX,
306→      centerY: el.centerY,
307→      bounds: el.bounds,
308→      clickable: el.clickable,
309→    })),
310→    count: elements.length,
311→    deviceId,
312→  };
313→
314→  if (elements.length === 0 && config.autoFallbackScreenshot) {
315→    const snapshot = await context.ui.visualSnapshot(deviceId, {
316→      includeBase64: config.includeBase64,
317→    });
318→    response.visualFallback = {
319→      ...snapshot,
320→      hint: "No elements matched selector. Use screenshot to identify tap coordinates.",
321→    };
322→  }
323→
324→  return response;
325→}
