 82→async function handleDump(
 83→  input: UiInput,
 84→  context: ServerContext,
 85→  _config: UiConfig,
 86→  deviceId: string
 87→): Promise<Record<string, unknown>> {
 88→  const tree = await context.ui.dump(deviceId);
 89→
 90→  const dumpId = context.cache.generateId("ui-dump");
 91→  context.cache.set(dumpId, { tree, deviceId }, "ui-dump", CACHE_TTLS.UI_TREE);
 92→
 93→  const emptyWarning = tree.length === 0
 94→    ? "No accessibility nodes found. Possible causes: (1) UI still loading - wait and retry, (2) App uses custom rendering (Flutter, games, video players) - use screenshot instead, (3) App blocks accessibility services."
 95→    : undefined;
 96→
 97→  if (input.compact !== false) {
 98→    return handleCompactDump(tree, input, dumpId, deviceId, emptyWarning);
 99→  }
100→
101→  return handleFullDump(tree, dumpId, deviceId, emptyWarning);
102→}
103→
104→function handleCompactDump(
105→  tree: AccessibilityNode[],
106→  input: UiInput,
107→  dumpId: string,
108→  deviceId: string,
109→  emptyWarning: string | undefined
110→): Record<string, unknown> {
111→  const flat = flattenTree(tree);
112→  const interactive = flat.filter((n) => n.clickable || n.focusable);
113→
114→  const limit = input.limit ?? 20;
115→  const offset = input.offset ?? 0;
116→  const totalCount = interactive.length;
117→  const paginated = interactive.slice(offset, offset + limit);
118→  const hasMore = offset + limit < totalCount;
119→
120→  const elements = paginated.map((n) => ({
121→    text: n.text || n.contentDesc || undefined,
122→    type: n.className.split(".").pop(),
123→    x: n.centerX,
124→    y: n.centerY,
125→    resourceId: n.resourceId ? n.resourceId.split("/").pop() : undefined,
126→  }));
127→
128→  const noInteractiveWarning = tree.length > 0 && totalCount === 0
129→    ? "Accessibility tree exists but no interactive elements found. Try 'ui find' with a text selector, or use screenshot for visual targeting."
130→    : undefined;
131→
132→  const hint = hasMore
133→    ? `${elements.length} of ${totalCount} elements shown. Use 'ui find' for specific elements, or add offset: ${offset + limit} for more.`
134→    : undefined;
135→
136→  return {
137→    dumpId,
138→    elements,
139→    count: elements.length,
140→    totalCount,
141→    hasMore,
142→    offset,
143→    limit,
144→    deviceId,
145→    hint,
146→    warning: emptyWarning || noInteractiveWarning,
147→  };
148→}
149→
150→function handleFullDump(
151→  tree: AccessibilityNode[],
152→  dumpId: string,
153→  deviceId: string,
154→  emptyWarning: string | undefined
155→): Record<string, unknown> {
156→  const simplifyNode = (node: AccessibilityNode): Record<string, unknown> => ({
157→    className: node.className.split(".").pop(),
158→    text: node.text || undefined,
159→    resourceId: node.resourceId ? node.resourceId.split("/").pop() : undefined,
160→    bounds: `[${node.bounds.left},${node.bounds.top}][${node.bounds.right},${node.bounds.bottom}]`,
161→    clickable: node.clickable || undefined,
162→    children: node.children?.map((c) => simplifyNode(c)),
163→  });
164→
165→  return {
166→    dumpId,
167→    tree: tree.map((n) => simplifyNode(n)),
168→    deviceId,
169→    warning: emptyWarning,
170→  };
171→}
