173→async function handleTap(
174→  input: UiInput,
175→  context: ServerContext,
176→  _config: UiConfig,
177→  deviceId: string
178→): Promise<Record<string, unknown>> {
179→  let x: number, y: number;
180→
181→  if (input.elementIndex !== undefined) {
182→    if (!context.lastFindResults[input.elementIndex]) {
183→      throw new ReplicantError(
184→        ErrorCode.ELEMENT_NOT_FOUND,
185→        `Element at index ${input.elementIndex} not found. Run 'find' first.`,
186→        "Use 'ui find' to locate elements, then reference them by index",
187→      );
188→    }
189→    const element = context.lastFindResults[input.elementIndex];
190→    const center = getElementCenter(element);
191→    x = center.x;
192→    y = center.y;
193→  } else if (input.x !== undefined && input.y !== undefined) {
194→    x = input.x;
195→    y = input.y;
196→  } else {
197→    throw new ReplicantError(
198→      ErrorCode.INPUT_VALIDATION_FAILED,
199→      "Either x/y coordinates or elementIndex is required for tap",
200→      "Provide x and y coordinates, or use elementIndex from a previous 'ui find' result",
201→    );
202→  }
203→
204→  await context.ui.tap(deviceId, x, y, input.deviceSpace);
205→  return { tapped: { x, y, deviceSpace: input.deviceSpace ?? false }, deviceId };
206→}
