  1→import * as fs from "fs";
  2→import * as os from "os";
  3→import * as path from "path";
  4→import { ReplicantError, ErrorCode } from "../types/index.js";
  5→
  6→export interface Environment {
  7→  sdkPath: string | null;
  8→  adbPath: string | null;
  9→  emulatorPath: string | null;
 10→  platform: "darwin" | "linux" | "win32";
 11→  isValid: boolean;
 12→  issues: string[];
 13→}
 14→
 15→export class EnvironmentService {
 16→  private cached: Environment | null = null;
 17→
 18→  async detect(): Promise<Environment> {
 19→    if (this.cached) {
 20→      return this.cached;
 21→    }
 22→
 23→    const platform = os.platform() as "darwin" | "linux" | "win32";
 24→    const issues: string[] = [];
 25→
 26→    // Try to find SDK
 27→    const sdkPath = this.findSdkPath(platform);
 28→
 29→    if (!sdkPath) {
 30→      this.cached = {
 31→        sdkPath: null,
 32→        adbPath: null,
 33→        emulatorPath: null,
 34→        platform,
 35→        isValid: false,
 36→        issues: ["Android SDK not found. Install Android Studio or set ANDROID_HOME environment variable."],
 37→      };
 38→      return this.cached;
 39→    }
 40→
 41→    const adbPath = path.join(sdkPath, "platform-tools", this.getExecutableName("adb", platform));
 42→    const emulatorPath = path.join(sdkPath, "emulator", this.getExecutableName("emulator", platform));
 43→
 44→    // Verify adb exists
 45→    if (!fs.existsSync(adbPath)) {
 46→      issues.push(`adb not found at ${adbPath}`);
 47→    }
 48→
 49→    // Emulator is optional - just note if missing
 50→    if (!fs.existsSync(emulatorPath)) {
 51→      issues.push(`emulator not found at ${emulatorPath} (optional)`);
 52→    }
 53→
 54→    this.cached = {
 55→      sdkPath,
 56→      adbPath: fs.existsSync(adbPath) ? adbPath : null,
 57→      emulatorPath: fs.existsSync(emulatorPath) ? emulatorPath : null,
 58→      platform,
 59→      isValid: fs.existsSync(adbPath),
 60→      issues,
 61→    };
 62→
 63→    return this.cached;
 64→  }
 65→
 66→  async getAdbPath(): Promise<string> {
 67→    const env = await this.detect();
 68→    if (!env.adbPath) {
 69→      throw new ReplicantError(
 70→        ErrorCode.ADB_NOT_FOUND,
 71→        "Android SDK not found",
 72→        "Install Android Studio or set ANDROID_HOME environment variable",
 73→        { checkedPaths: this.getSearchPaths(env.platform) }
 74→      );
 75→    }
 76→    return env.adbPath;
 77→  }
 78→
 79→  async getEmulatorPath(): Promise<string> {
 80→    const env = await this.detect();
 81→    if (!env.emulatorPath) {
 82→      throw new ReplicantError(
 83→        ErrorCode.EMULATOR_NOT_FOUND,
 84→        "Android emulator not found",
 85→        "Install Android Emulator via Android Studio SDK Manager"
 86→      );
 87→    }
 88→    return env.emulatorPath;
 89→  }
 90→
 91→  async getAvdManagerPath(): Promise<string> {
 92→    const env = await this.detect();
 93→    if (!env.sdkPath) {
 94→      throw new ReplicantError(
 95→        ErrorCode.SDK_NOT_FOUND,
 96→        "Android SDK not found",
 97→        "Install Android Studio or set ANDROID_HOME environment variable"
 98→      );
 99→    }
100→    const avdManagerPath = path.join(env.sdkPath, "cmdline-tools", "latest", "bin", this.getExecutableName("avdmanager", env.platform));
101→    // Fallback to older location
102→    const legacyPath = path.join(env.sdkPath, "tools", "bin", this.getExecutableName("avdmanager", env.platform));
103→
104→    if (fs.existsSync(avdManagerPath)) {
105→      return avdManagerPath;
106→    }
107→    if (fs.existsSync(legacyPath)) {
108→      return legacyPath;
109→    }
110→
111→    throw new ReplicantError(
112→      ErrorCode.SDK_NOT_FOUND,
113→      "avdmanager not found",
114→      "Install Android SDK Command-line Tools via Android Studio SDK Manager"
115→    );
116→  }
117→
118→  private findSdkPath(platform: string): string | null {
119→    // 1. Check ANDROID_HOME
120→    if (process.env.ANDROID_HOME) {
121→      const adbPath = path.join(process.env.ANDROID_HOME, "platform-tools", this.getExecutableName("adb", platform));
122→      if (fs.existsSync(adbPath)) {
123→        return process.env.ANDROID_HOME;
124→      }
125→    }
126→
127→    // 2. Check ANDROID_SDK_ROOT
128→    if (process.env.ANDROID_SDK_ROOT) {
129→      const adbPath = path.join(process.env.ANDROID_SDK_ROOT, "platform-tools", this.getExecutableName("adb", platform));
130→      if (fs.existsSync(adbPath)) {
131→        return process.env.ANDROID_SDK_ROOT;
132→      }
133→    }
134→
135→    // 3. Probe common paths
136→    const searchPaths = this.getSearchPaths(platform);
137→    for (const sdkPath of searchPaths) {
138→      const adbPath = path.join(sdkPath, "platform-tools", this.getExecutableName("adb", platform));
139→      if (fs.existsSync(adbPath)) {
140→        return sdkPath;
141→      }
142→    }
143→
144→    // 4. Probe PATH as last resort
145→    const adbInPath = this.findAdbInPath(platform);
146→    if (adbInPath) {
147→      // adb is at <SDK>/platform-tools/adb, go up 2 levels
148→      const platformToolsDir = this.getParentDir(adbInPath, platform);
149→      const sdkPath = this.getParentDir(platformToolsDir, platform);
150→      if (this.isValidSdkPath(sdkPath, platform)) {
151→        return sdkPath;
152→      }
153→    }
154→
155→    return null;
156→  }
157→
158→  private getSearchPaths(platform: string): string[] {
159→    const home = os.homedir();
160→
161→    if (platform === "darwin") {
162→      return [
163→        path.join(home, "Library", "Android", "sdk"),
164→        "/opt/homebrew/share/android-sdk",
165→        "/usr/local/share/android-sdk",
166→      ];
167→    }
168→
169→    if (platform === "linux") {
170→      return [
171→        path.join(home, "Android", "Sdk"),
172→        "/opt/android-sdk",
173→        "/usr/lib/android-sdk",
174→      ];
175→    }
176→
177→    if (platform === "win32") {
178→      const localAppData = process.env.LOCALAPPDATA || path.join(home, "AppData", "Local");
179→      return [
180→        path.join(localAppData, "Android", "Sdk"),
181→        "C:\\Android\\sdk",
182→      ];
183→    }
184→
185→    return [];
186→  }
187→
188→  // Clear cache (for testing)
189→  clearCache(): void {
190→    this.cached = null;
191→  }
192→
193→  private getExecutableName(baseName: string, platform?: string): string {
194→    const currentPlatform = platform ?? os.platform();
195→    if (currentPlatform !== "win32") {
196→      return baseName;
197→    }
198→
199→    const windowsExtensions: Record<string, string> = {
200→      adb: ".exe",
201→      emulator: ".exe",
202→      avdmanager: ".bat",
203→    };
204→
205→    return baseName + (windowsExtensions[baseName] || ".exe");
206→  }
207→
208→  private findAdbInPath(platform?: string): string | null {
209→    const actualPlatform = platform ?? os.platform();
210→    const adbName = this.getExecutableName("adb", actualPlatform);
211→    const pathEnv = process.env.PATH || "";
212→    const pathSeparator = actualPlatform === "win32" ? ";" : ":";
213→    const dirSeparator = actualPlatform === "win32" ? "\\" : "/";
214→
215→    for (const dir of pathEnv.split(pathSeparator)) {
216→      if (!dir) continue;
217→      // Use platform-appropriate path separator
218→      const candidate = dir + dirSeparator + adbName;
219→      if (fs.existsSync(candidate)) {
220→        return candidate;
221→      }
222→    }
223→    return null;
224→  }
225→
226→  private isValidSdkPath(sdkPath: string, platform?: string): boolean {
227→    // Valid SDK should have platform-tools directory with adb
228→    const actualPlatform = platform ?? os.platform();
229→    const separator = actualPlatform === "win32" ? "\\" : "/";
230→    const adbPath = sdkPath + separator + "platform-tools" + separator + this.getExecutableName("adb", platform);
231→    return fs.existsSync(adbPath);
232→  }
233→
234→  private getParentDir(filePath: string, platform?: string): string {
235→    const actualPlatform = platform ?? os.platform();
236→    const separator = actualPlatform === "win32" ? "\\" : "/";
237→    const parts = filePath.split(separator);
238→    parts.pop(); // Remove last component
239→    return parts.join(separator);
240→  }
241→}
