  1→// src/services/grid.ts
  2→import sharp from "sharp";
  3→
  4→export const GRID_COLS = 4;
  5→export const GRID_ROWS = 6;
  6→export const TOTAL_CELLS = GRID_COLS * GRID_ROWS; // 24
  7→
  8→export interface CellBounds {
  9→  x0: number;
 10→  y0: number;
 11→  x1: number;
 12→  y1: number;
 13→}
 14→
 15→/**
 16→ * Calculate the pixel bounds for a grid cell (1-24).
 17→ * Grid is 4 columns x 6 rows, numbered left-to-right, top-to-bottom.
 18→ */
 19→export function calculateGridCellBounds(
 20→  cell: number,
 21→  screenWidth: number,
 22→  screenHeight: number
 23→): CellBounds {
 24→  if (cell < 1 || cell > TOTAL_CELLS) {
 25→    throw new Error(`Invalid cell number: ${cell}. Must be 1-${TOTAL_CELLS}`);
 26→  }
 27→
 28→  const cellWidth = screenWidth / GRID_COLS;
 29→  const cellHeight = screenHeight / GRID_ROWS;
 30→
 31→  // Convert 1-based cell to 0-based row/col
 32→  const index = cell - 1;
 33→  const col = index % GRID_COLS;
 34→  const row = Math.floor(index / GRID_COLS);
 35→
 36→  return {
 37→    x0: Math.round(col * cellWidth),
 38→    y0: Math.round(row * cellHeight),
 39→    x1: Math.round((col + 1) * cellWidth),
 40→    y1: Math.round((row + 1) * cellHeight),
 41→  };
 42→}
 43→
 44→/**
 45→ * Calculate tap coordinates for a position within a cell.
 46→ * Position: 1=TL, 2=TR, 3=Center, 4=BL, 5=BR
 47→ */
 48→export function calculatePositionCoordinates(
 49→  position: 1 | 2 | 3 | 4 | 5,
 50→  cellBounds: CellBounds
 51→): { x: number; y: number } {
 52→  const width = cellBounds.x1 - cellBounds.x0;
 53→  const height = cellBounds.y1 - cellBounds.y0;
 54→
 55→  // Position multipliers (fraction of width/height from x0/y0)
 56→  const positionMap: Record<number, { xMult: number; yMult: number }> = {
 57→    1: { xMult: 0.25, yMult: 0.25 }, // Top-left
 58→    2: { xMult: 0.75, yMult: 0.25 }, // Top-right
 59→    3: { xMult: 0.5, yMult: 0.5 }, // Center
 60→    4: { xMult: 0.25, yMult: 0.75 }, // Bottom-left
 61→    5: { xMult: 0.75, yMult: 0.75 }, // Bottom-right
 62→  };
 63→
 64→  const { xMult, yMult } = positionMap[position];
 65→
 66→  return {
 67→    x: Math.round(cellBounds.x0 + width * xMult),
 68→    y: Math.round(cellBounds.y0 + height * yMult),
 69→  };
 70→}
 71→
 72→export const POSITION_LABELS = [
 73→  "Top-left",
 74→  "Top-right",
 75→  "Center",
 76→  "Bottom-left",
 77→  "Bottom-right",
 78→];
 79→
 80→const GRID_LINE_WIDTH = 3;
 81→const LABEL_FONT_SIZE = 36;
 82→
 83→const MAX_GRID_DIMENSION = 1000;
 84→const JPEG_QUALITY = 70;
 85→
 86→/**
 87→ * Create a 4x6 numbered grid overlay on a screenshot.
 88→ * Returns base64 JPEG (compressed for context efficiency).
 89→ */
 90→export async function createGridOverlay(imagePath: string): Promise<string> {
 91→  const image = sharp(imagePath);
 92→  const metadata = await image.metadata();
 93→  const width = metadata.width!;
 94→  const height = metadata.height!;
 95→
 96→  // Calculate scaling to fit within MAX_GRID_DIMENSION
 97→  const scaleFactor = Math.min(1, MAX_GRID_DIMENSION / Math.max(width, height));
 98→  const scaledWidth = Math.round(width * scaleFactor);
 99→  const scaledHeight = Math.round(height * scaleFactor);
100→
101→  const cellWidth = width / GRID_COLS;
102→  const cellHeight = height / GRID_ROWS;
103→
104→  // Create SVG overlay with grid lines and numbers
105→  const svgParts: string[] = [];
106→
107→  // Grid lines (vertical)
108→  for (let col = 1; col < GRID_COLS; col++) {
109→    const x = Math.round(col * cellWidth);
110→    svgParts.push(
111→      `<line x1="${x}" y1="0" x2="${x}" y2="${height}" stroke="rgba(255,165,0,0.8)" stroke-width="${GRID_LINE_WIDTH}"/>`
112→    );
113→  }
114→
115→  // Grid lines (horizontal)
116→  for (let row = 1; row < GRID_ROWS; row++) {
117→    const y = Math.round(row * cellHeight);
118→    svgParts.push(
119→      `<line x1="0" y1="${y}" x2="${width}" y2="${y}" stroke="rgba(255,165,0,0.8)" stroke-width="${GRID_LINE_WIDTH}"/>`
120→    );
121→  }
122→
123→  // Cell numbers
124→  for (let cell = 1; cell <= TOTAL_CELLS; cell++) {
125→    const index = cell - 1;
126→    const col = index % GRID_COLS;
127→    const row = Math.floor(index / GRID_COLS);
128→    const centerX = Math.round((col + 0.5) * cellWidth);
129→    const centerY = Math.round((row + 0.5) * cellHeight);
130→
131→    // Background circle for visibility
132→    svgParts.push(
133→      `<circle cx="${centerX}" cy="${centerY}" r="25" fill="rgba(0,0,0,0.6)"/>`
134→    );
135→    // Number text
136→    svgParts.push(
137→      `<text x="${centerX}" y="${centerY}" font-family="Arial, sans-serif" font-size="${LABEL_FONT_SIZE}" font-weight="bold" fill="white" text-anchor="middle" dominant-baseline="central">${cell}</text>`
138→    );
139→  }
140→
141→  const svgOverlay = `<svg width="${width}" height="${height}">${svgParts.join("")}</svg>`;
142→
143→  // Composite at original size first, then resize
144→  const composited = await image
145→    .composite([{ input: Buffer.from(svgOverlay), top: 0, left: 0 }])
146→    .toBuffer();
147→
148→  // Resize and compress to JPEG
149→  const buffer = await sharp(composited)
150→    .resize(scaledWidth, scaledHeight)
151→    .jpeg({ quality: JPEG_QUALITY })
152→    .toBuffer();
153→
154→  return buffer.toString("base64");
155→}
