 1→import sharp from "sharp";
 2→import { AccessibilityNode, Bounds } from "../parsers/ui-dump.js";
 3→
 4→export const MIN_ICON_SIZE = 16;
 5→export const MAX_ICON_SIZE = 200;
 6→export const MIN_ASPECT_RATIO = 0.5;
 7→export const MAX_ASPECT_RATIO = 2.0;
 8→export const MAX_CANDIDATES = 6;
 9→
10→/**
11→ * Check if dimensions are within icon size constraints.
12→ */
13→export function isIconSized(width: number, height: number): boolean {
14→  if (width < MIN_ICON_SIZE || width > MAX_ICON_SIZE) return false;
15→  if (height < MIN_ICON_SIZE || height > MAX_ICON_SIZE) return false;
16→
17→  const aspectRatio = width / height;
18→  if (aspectRatio < MIN_ASPECT_RATIO || aspectRatio > MAX_ASPECT_RATIO) return false;
19→
20→  return true;
21→}
22→
23→/**
24→ * Filter accessibility nodes to find unlabeled clickable elements that are icon-sized.
25→ * Returns max 6 candidates sorted by position (top-to-bottom, left-to-right).
26→ */
27→export function filterIconCandidates(nodes: AccessibilityNode[]): AccessibilityNode[] {
28→  const candidates = nodes.filter((node) => {
29→    // Must be clickable
30→    if (!node.clickable) return false;
31→
32→    // Must not have text or contentDesc (we're looking for unlabeled icons)
33→    if (node.text || node.contentDesc) return false;
34→
35→    // Must be icon-sized
36→    const width = node.bounds.right - node.bounds.left;
37→    const height = node.bounds.bottom - node.bounds.top;
38→    if (!isIconSized(width, height)) return false;
39→
40→    return true;
41→  });
42→
43→  // Sort by Y first (top-to-bottom), then X (left-to-right)
44→  candidates.sort((a, b) => {
45→    if (a.centerY !== b.centerY) return a.centerY - b.centerY;
46→    return a.centerX - b.centerX;
47→  });
48→
49→  // Limit to max candidates
50→  return candidates.slice(0, MAX_CANDIDATES);
51→}
52→
53→/**
54→ * Format candidate bounds as string "[x0,y0][x1,y1]"
55→ */
56→export function formatBounds(node: AccessibilityNode): string {
57→  return `[${node.bounds.left},${node.bounds.top}][${node.bounds.right},${node.bounds.bottom}]`;
58→}
59→
60→const MAX_CROP_SIZE = 128;
61→const JPEG_QUALITY = 70;
62→
63→/**
64→ * Crop a region from an image and return as base64 JPEG.
65→ * Scales down to max 128x128 if larger.
66→ */
67→export async function cropCandidateImage(
68→  imagePath: string,
69→  bounds: Bounds
70→): Promise<string> {
71→  const width = bounds.right - bounds.left;
72→  const height = bounds.bottom - bounds.top;
73→
74→  let pipeline = sharp(imagePath).extract({
75→    left: bounds.left,
76→    top: bounds.top,
77→    width,
78→    height,
79→  });
80→
81→  // Scale down if larger than max size
82→  if (width > MAX_CROP_SIZE || height > MAX_CROP_SIZE) {
83→    pipeline = pipeline.resize(MAX_CROP_SIZE, MAX_CROP_SIZE, {
84→      fit: "inside",
85→      withoutEnlargement: true,
86→    });
87→  }
88→
89→  const buffer = await pipeline.jpeg({ quality: JPEG_QUALITY }).toBuffer();
90→  return buffer.toString("base64");
91→}
