 1→import * as fs from "fs";
 2→import * as path from "path";
 3→import * as os from "os";
 4→
 5→export interface BaselineTestResult {
 6→  test: string;
 7→  status: "pass" | "fail" | "skip";
 8→}
 9→
10→export interface TestBaseline {
11→  savedAt: string;
12→  task: string;
13→  results: BaselineTestResult[];
14→}
15→
16→export interface Regression {
17→  test: string;
18→  previousStatus: string;
19→  currentStatus: string;
20→}
21→
22→function getBaselineDir(): string {
23→  const base = process.cwd() === "/" ? os.homedir() : process.cwd();
24→  return path.join(base, ".replicant", "test-baselines");
25→}
26→
27→function getBaselinePath(taskName: string): string {
28→  const safe = taskName.replace(/[^a-zA-Z0-9_-]/g, "_");
29→  return path.join(getBaselineDir(), `${safe}.json`);
30→}
31→
32→export function saveBaseline(taskName: string, results: BaselineTestResult[]): void {
33→  const dir = getBaselineDir();
34→  fs.mkdirSync(dir, { recursive: true });
35→  const baseline: TestBaseline = {
36→    savedAt: new Date().toISOString(),
37→    task: taskName,
38→    results,
39→  };
40→  fs.writeFileSync(getBaselinePath(taskName), JSON.stringify(baseline, null, 2));
41→}
42→
43→export function loadBaseline(taskName: string): TestBaseline | null {
44→  const filePath = getBaselinePath(taskName);
45→  if (!fs.existsSync(filePath)) return null;
46→  const content = fs.readFileSync(filePath, "utf-8");
47→  return JSON.parse(content) as TestBaseline;
48→}
49→
50→export function clearBaseline(taskName: string): void {
51→  const filePath = getBaselinePath(taskName);
52→  if (fs.existsSync(filePath)) {
53→    fs.unlinkSync(filePath);
54→  }
55→}
56→
57→export function compareResults(baseline: TestBaseline, current: BaselineTestResult[]): Regression[] {
58→  const currentMap = new Map(current.map(r => [r.test, r.status]));
59→  const regressions: Regression[] = [];
60→
61→  for (const prev of baseline.results) {
62→    if (prev.status === "pass") {
63→      const currentStatus = currentMap.get(prev.test);
64→      if (currentStatus && currentStatus !== "pass") {
65→        regressions.push({
66→          test: prev.test,
67→          previousStatus: prev.status,
68→          currentStatus,
69→        });
70→      }
71→    }
72→  }
73→
74→  return regressions;
75→}
