64→export class ReplicantError extends Error {
65→  constructor(
66→    public readonly code: ErrorCode,
67→    message: string,
68→    public readonly suggestion?: string,
69→    public readonly context?: ErrorContext
70→  ) {
71→    super(message);
72→    this.name = "ReplicantError";
73→  }
74→
75→  toJSON() {
76→    return {
77→      error: this.code,
78→      message: this.message,
79→      suggestion: this.suggestion,
80→      context: this.context,
81→    };
82→  }
83→
84→  toToolError(): ToolError {
85→    return {
86→      error: this.code,
87→      message: this.message,
88→      suggestion: this.suggestion,
89→      details: this.context,
90→    };
91→  }
