 1→import { Device, ReplicantError, ErrorCode } from "../types/index.js";
 2→import type { AdbAdapter } from "../adapters/adb.js";
 3→
 4→export class DeviceStateManager {
 5→  private currentDevice: Device | null = null;
 6→
 7→  getCurrentDevice(): Device | null {
 8→    return this.currentDevice;
 9→  }
10→
11→  setCurrentDevice(device: Device): void {
12→    this.currentDevice = device;
13→  }
14→
15→  clearCurrentDevice(): void {
16→    this.currentDevice = null;
17→  }
18→
19→  requireCurrentDevice(): Device {
20→    if (!this.currentDevice) {
21→      throw new ReplicantError(
22→        ErrorCode.NO_DEVICE_SELECTED,
23→        "No device selected",
24→        "Call adb-device({ operation: 'list' }) to see available devices"
25→      );
26→    }
27→    return this.currentDevice;
28→  }
29→
30→  async ensureDevice(adb: AdbAdapter): Promise<Device> {
31→    // Already selected? Use it.
32→    if (this.currentDevice) {
33→      return this.currentDevice;
34→    }
35→
36→    // Try to auto-select
37→    const devices = await adb.getDevices();
38→
39→    if (devices.length === 0) {
40→      throw new ReplicantError(
41→        ErrorCode.NO_DEVICES,
42→        "No devices connected",
43→        "Start an emulator with 'emulator-device start' or connect a USB device with debugging enabled"
44→      );
45→    }
46→
47→    if (devices.length === 1) {
48→      this.currentDevice = devices[0];
49→      return this.currentDevice;
50→    }
51→
52→    // Multiple devices - user must choose
53→    const deviceList = devices.map((d) => d.id).join(", ");
54→    throw new ReplicantError(
55→      ErrorCode.MULTIPLE_DEVICES,
56→      `${devices.length} devices connected: ${deviceList}`,
57→      `Call adb-device({ operation: 'select', deviceId: '...' }) to choose one`
58→    );
59→  }
60→
61→  autoSelectIfSingle(devices: Device[]): boolean {
62→    if (devices.length === 1 && !this.currentDevice) {
63→      this.currentDevice = devices[0];
64→      return true;
65→    }
66→    return false;
67→  }
68→}
