 98→async function dispatchToolCall(
 99→  name: string,
100→  args: Record<string, unknown> | undefined,
101→  context: ServerContext
102→): Promise<Record<string, unknown>> {
103→  const rawArgs = args ?? {};
104→
105→  const parseOrThrow = <T>(toolName: string, parser: { parse: (data: unknown) => T }): T => {
106→    try {
107→      return parser.parse(rawArgs);
108→    } catch (error) {
109→      if (error instanceof ZodError) {
110→        const message = error.issues
111→          .map((issue) => {
112→            const path = issue.path.length > 0 ? issue.path.join(".") : "input";
113→            return `${path}: ${issue.message}`;
114→          })
115→          .join("; ");
116→
117→        throw new ReplicantError(
118→          ErrorCode.INPUT_VALIDATION_FAILED,
119→          `Invalid input for ${toolName}: ${message}`,
120→          "Check the tool input schema and provide valid arguments",
121→        );
122→      }
123→
124→      throw error;
125→    }
126→  };
127→
128→  switch (name) {
129→    case "cache":
130→      return handleCacheTool(parseOrThrow("cache", cacheInputSchema), context.cache);
131→    case "rtfm":
132→      return handleRtfmTool(parseOrThrow("rtfm", rtfmInputSchema));
133→    case "adb-device":
134→      return handleAdbDeviceTool(parseOrThrow("adb-device", adbDeviceInputSchema), context);
135→    case "adb-app":
136→      return handleAdbAppTool(parseOrThrow("adb-app", adbAppInputSchema), context);
137→    case "adb-logcat":
138→      return handleAdbLogcatTool(parseOrThrow("adb-logcat", adbLogcatInputSchema), context);
139→    case "adb-shell":
140→      return handleAdbShellTool(parseOrThrow("adb-shell", adbShellInputSchema), context);
141→    case "emulator-device":
142→      return handleEmulatorDeviceTool(parseOrThrow("emulator-device", emulatorDeviceInputSchema), context);
143→    case "gradle-build":
144→      return handleGradleBuildTool(parseOrThrow("gradle-build", gradleBuildInputSchema), context);
145→    case "gradle-test":
146→      return handleGradleTestTool(parseOrThrow("gradle-test", gradleTestInputSchema), context);
147→    case "gradle-list":
148→      return handleGradleListTool(parseOrThrow("gradle-list", gradleListInputSchema), context);
149→    case "gradle-get-details":
150→      return handleGradleGetDetailsTool(parseOrThrow("gradle-get-details", gradleGetDetailsInputSchema), context);

 1→/**
 2→ * Calculate the scale factor needed to fit device dimensions within max dimension.
 3→ * Returns 1.0 if no scaling needed.
 4→ */
 5→export function calculateScaleFactor(
 6→  deviceWidth: number,
 7→  deviceHeight: number,
 8→  maxDimension: number
 9→): number {
10→  const longestSide = Math.max(deviceWidth, deviceHeight);
11→  if (longestSide <= maxDimension) {
12→    return 1.0;
13→  }
14→  return longestSide / maxDimension;
15→}
16→
17→export interface Bounds {
18→  left: number;
19→  top: number;
20→  right: number;
21→  bottom: number;
22→}
23→
24→/**
25→ * Convert device coordinates to image coordinates.
26→ */
27→export function toImageSpace(
28→  deviceX: number,
29→  deviceY: number,
30→  scaleFactor: number
31→): { x: number; y: number } {
32→  if (scaleFactor === 1.0) {
33→    return { x: deviceX, y: deviceY };
34→  }
35→  return {
36→    x: Math.round(deviceX / scaleFactor),
37→    y: Math.round(deviceY / scaleFactor),
38→  };
39→}
40→
41→/**
42→ * Convert image coordinates to device coordinates.
43→ */
44→export function toDeviceSpace(
45→  imageX: number,
46→  imageY: number,
47→  scaleFactor: number
48→): { x: number; y: number } {
49→  if (scaleFactor === 1.0) {
50→    return { x: imageX, y: imageY };
51→  }
52→  return {
53→    x: Math.round(imageX * scaleFactor),
54→    y: Math.round(imageY * scaleFactor),
55→  };
56→}
57→
58→/**
59→ * Convert bounds from device space to image space.
60→ */
61→export function boundsToImageSpace(bounds: Bounds, scaleFactor: number): Bounds {
62→  if (scaleFactor === 1.0) {
63→    return bounds;
64→  }
65→  return {
66→    left: Math.round(bounds.left / scaleFactor),
67→    top: Math.round(bounds.top / scaleFactor),
68→    right: Math.round(bounds.right / scaleFactor),
69→    bottom: Math.round(bounds.bottom / scaleFactor),
70→  };
71→}
