 1→import { readFile } from "fs/promises";
 2→import { existsSync } from "fs";
 3→import { parse as parseYaml } from "yaml";
 4→import { ReplicantConfig, DEFAULT_CONFIG, UiConfig, BuildConfig } from "../types/config.js";
 5→import { logger } from "../utils/logger.js";
 6→
 7→/**
 8→ * Load configuration from REPLICANT_CONFIG environment variable path
 9→ * Falls back to defaults if not set or file doesn't exist
10→ */
11→export async function loadConfig(): Promise<ReplicantConfig> {
12→  const configPath = process.env.REPLICANT_CONFIG;
13→
14→  if (!configPath) {
15→    return DEFAULT_CONFIG;
16→  }
17→
18→  if (!existsSync(configPath)) {
19→    logger.warn("REPLICANT_CONFIG set but file not found", { path: configPath });
20→    return DEFAULT_CONFIG;
21→  }
22→
23→  try {
24→    const content = await readFile(configPath, "utf-8");
25→    const parsed = parseYaml(content) as Partial<ReplicantConfig> | null;
26→
27→    if (!parsed) {
28→      return DEFAULT_CONFIG;
29→    }
30→
31→    // Deep merge with defaults
32→    return {
33→      ui: mergeUiConfig(DEFAULT_CONFIG.ui, parsed.ui),
34→      build: mergeBuildConfig(DEFAULT_CONFIG.build, parsed.build),
35→    };
36→  } catch (error) {
37→    const message = error instanceof Error ? error.message : String(error);
38→    logger.warn("Failed to parse REPLICANT_CONFIG", { path: configPath, error: message });
39→    return DEFAULT_CONFIG;
40→  }
41→}
42→
43→function mergeBuildConfig(defaults: BuildConfig, overrides?: Partial<BuildConfig>): BuildConfig {
44→  if (!overrides) {
45→    return defaults;
46→  }
47→
48→  return {
49→    projectRoot: overrides.projectRoot ?? defaults.projectRoot,
50→  };
51→}
52→
53→function mergeUiConfig(defaults: UiConfig, overrides?: Partial<UiConfig>): UiConfig {
54→  if (!overrides) {
55→    return defaults;
56→  }
57→
58→  return {
59→    visualModePackages: overrides.visualModePackages ?? defaults.visualModePackages,
60→    autoFallbackScreenshot: overrides.autoFallbackScreenshot ?? defaults.autoFallbackScreenshot,
61→    includeBase64: overrides.includeBase64 ?? defaults.includeBase64,
62→    maxImageDimension: overrides.maxImageDimension ?? defaults.maxImageDimension,
63→  };
64→}
65→
66→/**
67→ * ConfigManager holds the loaded configuration and provides access to it
68→ */
69→export class ConfigManager {
70→  private config: ReplicantConfig = DEFAULT_CONFIG;
71→
72→  async load(): Promise<void> {
73→    this.config = await loadConfig();
74→  }
75→
76→  get(): ReplicantConfig {
77→    return this.config;
78→  }
79→
80→  getUiConfig(): UiConfig {
81→    return this.config.ui;
82→  }
83→
84→  getBuildConfig(): BuildConfig {
85→    return this.config.build;
86→  }
87→
88→  isVisualModePackage(packageName: string): boolean {
89→    return this.config.ui.visualModePackages.includes(packageName);
90→  }
91→}
