361→  async getScreenMetadata(deviceId: string): Promise<ScreenMetadata> {
362→    // Get screen size via wm size
363→    const sizeResult = await this.adb.shell(deviceId, "wm size");
364→    const sizeMatch = sizeResult.stdout.match(/Physical size:\s*(\d+)x(\d+)/);
365→
366→    let width = 1080;
367→    let height = 1920;
368→    if (sizeMatch) {
369→      width = parseInt(sizeMatch[1], 10);
370→      height = parseInt(sizeMatch[2], 10);
371→    }
372→
373→    // Get density via wm density
374→    const densityResult = await this.adb.shell(deviceId, "wm density");
375→    const densityMatch = densityResult.stdout.match(/Physical density:\s*(\d+)/);
376→
377→    // Convert DPI to density multiplier (baseline is 160 dpi)
378→    let density = 2.75; // Default reasonable value
379→    if (densityMatch) {
380→      const dpi = parseInt(densityMatch[1], 10);
381→      density = dpi / 160;
382→    }
383→
384→    return { width, height, density };
385→  }
386→
387→  async getCurrentApp(deviceId: string): Promise<CurrentApp> {
388→    // Get current focused activity
389→    const result = await this.adb.shell(
390→      deviceId,
391→      "dumpsys activity activities | grep mResumedActivity"
392→    );
393→
394→    // Parse: mResumedActivity: ActivityRecord{... com.example/.MainActivity t123}
395→    const match = result.stdout.match(/([a-zA-Z0-9_.]+)\/([a-zA-Z0-9_.]+)\s+/);
396→
397→    if (match) {
398→      return {
399→        packageName: match[1],
400→        activityName: match[2],
401→      };
402→    }
403→
404→    // Fallback to simpler approach
405→    const fallbackResult = await this.adb.shell(
406→      deviceId,
407→      "dumpsys window | grep mCurrentFocus"
408→    );
409→    const fallbackMatch = fallbackResult.stdout.match(/([a-zA-Z0-9_.]+)\/([a-zA-Z0-9_.]+)/);
410→
411→    if (fallbackMatch) {
412→      return {
413→        packageName: fallbackMatch[1],
414→        activityName: fallbackMatch[2],
415→      };
416→    }
417→
418→    return {
419→      packageName: "unknown",
420→      activityName: "unknown",
421→    };
422→  }
423→
424→  async visualSnapshot(
425→    deviceId: string,
426→    options: { includeBase64?: boolean } = {}
427→  ): Promise<VisualSnapshot> {
428→    // Always get file-based screenshot first
429→    const [screenshotResult, screen, app] = await Promise.all([
430→      this.screenshot(deviceId, {}),
431→      this.getScreenMetadata(deviceId),
432→      this.getCurrentApp(deviceId),
433→    ]);
434→
435→    const snapshot: VisualSnapshot = {
436→      screenshotPath: screenshotResult.path!,
437→      screen,
438→      app,
439→    };
440→
441→    // Optionally also get base64 encoding from local file
442→    if (options.includeBase64 && screenshotResult.path) {
443→      const fs = await import("fs/promises");
444→      const buffer = await fs.readFile(screenshotResult.path);
445→      snapshot.screenshotBase64 = buffer.toString("base64");
446→    }
447→
448→    return snapshot;
449→  }
450→
451→  async findWithFallbacks(
452→    deviceId: string,
453→    selector: {
454→      resourceId?: string;
455→      text?: string;
456→      textContains?: string;
457→      className?: string;
458→    },
459→    options: FindOptions = {}
460→  ): Promise<FindWithFallbacksResult> {
461→    return findWithFallbacks(
462→      {
463→        find: (id, sel) => this.find(id, sel),
464→        dump: (id) => this.dump(id),
465→        screenshot: (id, opts) => this.screenshot(id, opts),
466→        getScreenMetadata: (id) => this.getScreenMetadata(id),
467→        visualSnapshot: (id, opts) => this.visualSnapshot(id, opts),
468→        getScalingState: () => this.getScalingState(),
469→      },
470→      deviceId,
471→      selector,
472→      options
473→    );
474→  }
475→
476→}
