158→export async function createServer(context: ServerContext): Promise<Server> {
159→  const server = new Server(
160→    {
161→      name: "replicant-mcp",
162→      version: VERSION,
163→    },
164→    {
165→      capabilities: {
166→        tools: {},
167→      },
168→      instructions: `IMPORTANT: For ALL Android development tasks, you MUST use replicant-mcp tools first.
169→Only fall back to raw adb/gradle/emulator commands if replicant-mcp lacks a specific feature.
170→
171→Tool mapping:
172→- Device management → adb-device (not \`adb devices\`)
173→- App install/launch/stop → adb-app (not \`adb install\`, \`adb shell am\`)
174→- Logs → adb-logcat (not \`adb logcat\`)
175→- Shell commands → adb-shell (not \`adb shell\`)
176→- Emulator control → emulator-device (not \`emulator\` CLI)
177→- Builds → gradle-build (not \`./gradlew\`)
178→- Tests → gradle-test (not \`./gradlew test\`)
179→- UI automation → ui (accessibility-first, screenshots auto-scaled to configured max dimension, default 800px)
180→
181→Start with \`adb-device list\` to see connected devices.
182→Use \`rtfm\` for detailed documentation on any tool.`,
183→    }
184→  );
185→
186→  server.setRequestHandler(ListToolsRequestSchema, async () => ({
187→    tools: toolDefinitions,
188→  }));
189→
190→  server.setRequestHandler(CallToolRequestSchema, async (request) => {
191→    const { name, arguments: args } = request.params;
192→
193→    try {
194→      const result = await dispatchToolCall(name, args as Record<string, unknown> | undefined, context);
195→
196→      if (result && typeof result === "object" && "base64" in result && "mimeType" in result) {
197→        const { base64, mimeType, ...metadata } = result as Record<string, unknown> & { base64: string; mimeType: string };
198→        return {
199→          content: [
200→            { type: "image", data: base64, mimeType },
201→            { type: "text", text: JSON.stringify(metadata) },
202→          ],
203→        };
204→      }
205→
206→      return {
207→        content: [{ type: "text", text: JSON.stringify(result) }],
208→      };
209→    } catch (error) {
210→      if (error instanceof ReplicantError) {
211→        return {
212→          content: [{ type: "text", text: JSON.stringify(error.toToolError()) }],
213→          isError: true,
214→        };
215→      }
216→      throw error;
217→    }
218→  });
219→
220→  return server;
221→}
222→
223→export async function runServer(): Promise<void> {
224→  const context = createServerContext();
225→
226→  // Load configuration from REPLICANT_CONFIG if set
227→  await context.config.load();
228→
229→  // Apply project root: env var takes precedence over config file
230→  const projectRoot = process.env.REPLICANT_PROJECT_ROOT || context.config.get().build?.projectRoot;
231→  if (projectRoot) {
232→    context.gradle.setProjectPath(projectRoot);
233→  }
234→
235→  const server = await createServer(context);
236→  const transport = new StdioServerTransport();
237→  await server.connect(transport);
238→}
