  1→import { execa, ExecaError } from "execa";
  2→import { ReplicantError, ErrorCode } from "../types/index.js";
  3→import type { EnvironmentService } from "./environment.js";
  4→
  5→export interface RunOptions {
  6→  timeoutMs?: number;
  7→  cwd?: string;
  8→}
  9→
 10→export interface RunResult {
 11→  stdout: string;
 12→  stderr: string;
 13→  exitCode: number;
 14→}
 15→
 16→const BLOCKED_COMMANDS = new Set(["reboot", "shutdown", "halt", "poweroff"]);
 17→
 18→const BLOCKED_PATTERNS = [
 19→  /^rm\s+(-[rf]+\s+)*\//, // rm -rf /
 20→  /^su(\s|$)/, // su
 21→  /^sudo(\s|$)/, // sudo
 22→  /\bformat\b/, // format commands
 23→];
 24→
 25→const BLOCKED_SHELL_PATTERNS = [
 26→  /^rm\s+(-[rf]+\s+)*\/\s*$/, // rm -rf / (root itself)
 27→  /^rm\s+(-[rf]+\s+)*\/(system|vendor|oem|product)(\/|\s|$)/, // rm on system partitions
 28→  /^su(\s|$)/, // su
 29→  /^sudo(\s|$)/, // sudo
 30→  /\bformat\b/, // format commands
 31→  /^setprop\s+persist\./, // persistent property changes
 32→  /^dd\s/, // raw disk operations
 33→  /^mkfs/, // filesystem creation
 34→  /^flash/, // flash operations
 35→  /^wipe/, // wipe data/cache
 36→  /^recovery\b/, // recovery mode
 37→  /^reboot\b/, // reboot device (also in BLOCKED_COMMANDS)
 38→];
 39→
 40→export class ProcessRunner {
 41→  private readonly defaultTimeoutMs = 30_000;
 42→  private readonly maxTimeoutMs = 120_000;
 43→
 44→  constructor(private environment?: EnvironmentService) {}
 45→
 46→  async run(
 47→    command: string,
 48→    args: string[],
 49→    options: RunOptions = {}
 50→  ): Promise<RunResult> {
 51→    this.validateCommand(command, args);
 52→
 53→    const timeoutMs = Math.min(
 54→      options.timeoutMs ?? this.defaultTimeoutMs,
 55→      this.maxTimeoutMs
 56→    );
 57→
 58→    try {
 59→      const result = await execa(command, args, {
 60→        timeout: timeoutMs,
 61→        cwd: options.cwd,
 62→      });
 63→
 64→      return {
 65→        stdout: result.stdout,
 66→        stderr: result.stderr,
 67→        exitCode: result.exitCode ?? 0,
 68→      };
 69→    } catch (error: unknown) {
 70→      if (error instanceof ExecaError) {
 71→        if (error.timedOut) {
 72→          throw new ReplicantError(
 73→            ErrorCode.TIMEOUT,
 74→            `Command timed out after ${timeoutMs}ms`,
 75→            "Try increasing the timeout or simplifying the command"
 76→          );
 77→        }
 78→        return {
 79→          stdout: (error.stdout ?? "") as string,
 80→          stderr: (error.stderr ?? "") as string,
 81→          exitCode: error.exitCode ?? 1,
 82→        };
 83→      }
 84→      throw error;
 85→    }
 86→  }
 87→
 88→  async runAdb(args: string[], options: RunOptions = {}): Promise<RunResult> {
 89→    if (!this.environment) {
 90→      // Fallback to bare "adb" if no environment service
 91→      return this.run("adb", args, options);
 92→    }
 93→
 94→    const adbPath = await this.environment.getAdbPath();
 95→    return this.run(adbPath, args, options);
 96→  }
 97→
 98→  async runEmulator(args: string[], options: RunOptions = {}): Promise<RunResult> {
 99→    if (!this.environment) {
100→      return this.run("emulator", args, options);
101→    }
102→
103→    const emulatorPath = await this.environment.getEmulatorPath();
104→    return this.run(emulatorPath, args, options);
105→  }
106→
107→  async runAvdManager(args: string[], options: RunOptions = {}): Promise<RunResult> {
108→    if (!this.environment) {
109→      return this.run("avdmanager", args, options);
110→    }
111→
112→    const avdManagerPath = await this.environment.getAvdManagerPath();
113→    return this.run(avdManagerPath, args, options);
114→  }
115→
116→  private validateCommand(command: string, args: string[]): void {
117→    if (BLOCKED_COMMANDS.has(command)) {
118→      throw new ReplicantError(
119→        ErrorCode.COMMAND_BLOCKED,
120→        `Command '${command}' is not allowed`,
121→        "Use safe commands only"
122→      );
123→    }
124→
125→    const fullCommand = `${command} ${args.join(" ")}`;
126→    for (const pattern of BLOCKED_PATTERNS) {
127→      if (pattern.test(fullCommand)) {
128→        throw new ReplicantError(
129→          ErrorCode.COMMAND_BLOCKED,
130→          `Command '${fullCommand}' is not allowed`,
131→          "Use safe commands only"
132→        );
133→      }
134→    }
135→
136→    this.validateShellPayload(command, args);
137→  }
138→
139→  private validateShellPayload(command: string, args: string[]): void {
140→    // Only validate shell payloads for adb commands
141→    const basename = command.split("/").pop() ?? command;
142→    if (basename !== "adb") return;
143→    const shellIndex = args.indexOf("shell");
144→    if (shellIndex === -1 || shellIndex >= args.length - 1) return;
145→
146→    let payloadArgs = args.slice(shellIndex + 1);
147→    // Strip leading "--" (end-of-options marker)
148→    if (payloadArgs[0] === "--") {
149→      payloadArgs = payloadArgs.slice(1);
150→    }
151→
152→    const shellPayload = payloadArgs.join(" ").trim();
153→    if (!shellPayload) return;
154→
155→    // Block shell metacharacters that enable command chaining/substitution.
156→    // $letter/$(/$ are blocked (variable expansion, command substitution) but
157→    // bare $ before digits is allowed (e.g., input text '$100').
158→    if (/[;&|`()]|\$[({a-zA-Z_]/.test(shellPayload)) {
159→      throw new ReplicantError(
160→        ErrorCode.COMMAND_BLOCKED,
161→        "Shell metacharacters are not allowed in shell commands",
162→        "Use simple commands without chaining, pipes, or substitution"
163→      );
164→    }
165→
166→    // Block shell wrapper commands (sh -c, bash -c)
167→    if (/^(sh|bash|dash|zsh)\s+-c\b/.test(shellPayload)) {
168→      throw new ReplicantError(
169→        ErrorCode.COMMAND_BLOCKED,
170→        "Shell interpreters with -c are not allowed",
171→        "Run the command directly without a shell wrapper"
172→      );
173→    }
174→
175→    const shellCommand = shellPayload.split(/\s+/)[0];
176→    if (BLOCKED_COMMANDS.has(shellCommand)) {
177→      throw new ReplicantError(
178→        ErrorCode.COMMAND_BLOCKED,
179→        `Shell command '${shellPayload}' is not allowed`,
180→        "Use safe commands only"
181→      );
182→    }
183→
184→    for (const pattern of BLOCKED_SHELL_PATTERNS) {
185→      if (pattern.test(shellPayload)) {
186→        throw new ReplicantError(
187→          ErrorCode.COMMAND_BLOCKED,
188→          `Shell command '${shellPayload}' is not allowed`,
189→          "Use safe commands only"
190→        );
191→      }
192→    }
193→  }
194→}
