 77→async function handleList(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 78→  const allPackages = await context.adb.getPackages(deviceId);
 79→  const limit = input.limit ?? 20;
 80→  const offset = input.offset ?? 0;
 81→  const filter = input.filter?.toLowerCase();
 82→
 83→  const filtered = filter
 84→    ? allPackages.filter((pkg) => pkg.toLowerCase().includes(filter))
 85→    : allPackages;
 86→
 87→  const paginated = filtered.slice(offset, offset + limit);
 88→  const hasMore = offset + limit < filtered.length;
 89→
 90→  const cacheId = context.cache.generateId("app-list");
 91→  context.cache.set(
 92→    cacheId,
 93→    { packages: filtered, deviceId, filter: filter || null },
 94→    "app-list",
 95→    CACHE_TTLS.APP_LIST
 96→  );
 97→
 98→  return {
 99→    packages: paginated,
100→    count: paginated.length,
101→    totalCount: filtered.length,
102→    hasMore,
103→    offset,
104→    limit,
105→    cacheId,
106→    deviceId,
107→  };
108→}
