103→  private async gradle(
104→    args: string[],
105→    timeoutMs = 120000
106→  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
107→    const gradleCmd = process.platform === "win32" ? "gradlew.bat" : "./gradlew";
108→
109→    try {
110→      return await this.runner.run(gradleCmd, args, {
111→        timeoutMs,
112→        cwd: this.projectPath,
113→      });
114→    } catch (error) {
115→      if (error instanceof Error && error.message.includes("ENOENT")) {
116→        throw new ReplicantError(
117→          ErrorCode.GRADLE_NOT_FOUND,
118→          "Gradle wrapper not found",
119→          "Set REPLICANT_PROJECT_ROOT to your Android project directory, " +
120→          "or add build.projectRoot to your config file. " +
121→          "See: https://github.com/thecombatwombat/replicant-mcp#configuration"
122→        );
123→      }
124→      throw error;
125→    }
126→  }
