151→    properties: {
152→      operation: {
153→        type: "string",
154→        enum: ["list", "select", "wait", "properties", "health-check"],
155→      },
156→      deviceId: { type: "string", description: "Device ID for select/wait/properties" },
157→    },
158→    required: ["operation"],
159→  },
