 29→async function handleUninstall(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 30→  if (!input.packageName) {
 31→    throw new ReplicantError(
 32→      ErrorCode.INPUT_VALIDATION_FAILED,
 33→      "packageName is required for uninstall operation",
 34→      "Provide the package name to uninstall",
 35→    );
 36→  }
 37→  await context.adb.uninstall(deviceId, input.packageName);
 38→  return { uninstalled: input.packageName, deviceId };
