 65→async function handleClearData(input: AdbAppInput, deviceId: string, context: ServerContext): Promise<Record<string, unknown>> {
 66→  if (!input.packageName) {
 67→    throw new ReplicantError(
 68→      ErrorCode.INPUT_VALIDATION_FAILED,
 69→      "packageName is required for clear-data operation",
 70→      "Provide the package name to clear data for",
 71→    );
 72→  }
 73→  await context.adb.clearData(deviceId, input.packageName);
 74→  return { cleared: input.packageName, deviceId };
