112→const operations: Record<string, AppHandler> = {
113→  install: handleInstall,
114→  uninstall: handleUninstall,
115→  launch: handleLaunch,
116→  stop: handleStop,
117→  "clear-data": handleClearData,
118→  list: handleList,
119→};
