  1→import { flattenTree, AccessibilityNode } from "../parsers/ui-dump.js";
  2→import { extractText, searchText } from "../services/ocr.js";
  3→import { matchIconPattern, matchesResourceId } from "../services/icon-patterns.js";
  4→import { filterIconCandidates, formatBounds, cropCandidateImage } from "../services/visual-candidates.js";
  5→import {
  6→  calculateGridCellBounds,
  7→  calculatePositionCoordinates,
  8→  createGridOverlay,
  9→  POSITION_LABELS,
 10→} from "../services/grid.js";
 11→import {
 12→  FindWithFallbacksResult,
 13→  FindOptions,
 14→  FindTier,
 15→  VisualCandidate,
 16→} from "../types/icon-recognition.js";
 17→import type { ScreenMetadata, ScalingState, ScreenshotResult } from "./ui-automator.js";
 18→import type { VisualSnapshot } from "../types/index.js";
 19→
 20→export interface FallbackFindDeps {
 21→  find(deviceId: string, selector: Record<string, string | undefined>): Promise<AccessibilityNode[]>;
 22→  dump(deviceId: string): Promise<AccessibilityNode[]>;
 23→  screenshot(deviceId: string, options?: Record<string, unknown>): Promise<ScreenshotResult>;
 24→  getScreenMetadata(deviceId: string): Promise<ScreenMetadata>;
 25→  visualSnapshot(deviceId: string, options?: { includeBase64?: boolean }): Promise<VisualSnapshot>;
 26→  getScalingState(): ScalingState | null;
 27→}
 28→
 29→function createEarlyStopResult(
 30→  tier: FindTier,
 31→  source: "accessibility" | "ocr" | "visual"
 32→): FindWithFallbacksResult {
 33→  return {
 34→    elements: [],
 35→    source,
 36→    tier,
 37→    confidence: "low",
 38→    stoppedEarly: true,
 39→    stoppedAtTier: tier,
 40→    nextTierAvailable: tier < 5 ? ((tier + 1) as FindTier) : undefined,
 41→    stopReason: "maxTier limit reached",
 42→  };
 43→}
 44→
 45→export async function findWithFallbacks(
 46→  deps: FallbackFindDeps,
 47→  deviceId: string,
 48→  selector: {
 49→    resourceId?: string;
 50→    text?: string;
 51→    textContains?: string;
 52→    className?: string;
 53→  },
 54→  options: FindOptions = {}
 55→): Promise<FindWithFallbacksResult> {
 56→  const maxTier = options.maxTier ?? 5;
 57→
 58→  // Handle Tier 5 grid refinement FIRST (when gridCell and gridPosition are provided)
 59→  if (options.gridCell !== undefined && options.gridPosition !== undefined) {
 60→    let width: number, height: number;
 61→    const scalingState = deps.getScalingState();
 62→    if (scalingState && scalingState.scaleFactor !== 1.0) {
 63→      width = scalingState.imageWidth;
 64→      height = scalingState.imageHeight;
 65→    } else {
 66→      const screen = await deps.getScreenMetadata(deviceId);
 67→      width = screen.width;
 68→      height = screen.height;
 69→    }
 70→    const cellBounds = calculateGridCellBounds(options.gridCell, width, height);
 71→    const coords = calculatePositionCoordinates(options.gridPosition, cellBounds);
 72→
 73→    return {
 74→      elements: [
 75→        {
 76→          index: 0,
 77→          bounds: `[${cellBounds.x0},${cellBounds.y0}][${cellBounds.x1},${cellBounds.y1}]`,
 78→          center: coords,
 79→        },
 80→      ],
 81→      source: "grid",
 82→      tier: 5,
 83→      confidence: "low",
 84→    };
 85→  }
 86→
 87→  // Tier 1: Accessibility text match
 88→  const accessibilityResults = await deps.find(deviceId, selector);
 89→
 90→  if (accessibilityResults.length > 0) {
 91→    return {
 92→      elements: accessibilityResults,
 93→      source: "accessibility",
 94→      tier: 1,
 95→      confidence: "high",
 96→    };
 97→  }
 98→
 99→  if (maxTier === 1) {
100→    return createEarlyStopResult(1, "accessibility");
101→  }
102→
103→  // Tier 2: ResourceId pattern match (for text-based queries)
104→  if (selector.text || selector.textContains) {
105→    const query = selector.text || selector.textContains!;
106→    const patterns = matchIconPattern(query);
107→
108→    if (patterns) {
109→      const tree = await deps.dump(deviceId);
110→      const flat = flattenTree(tree);
111→      const patternMatches = flat.filter(
112→        (node) => node.resourceId && matchesResourceId(node.resourceId, patterns)
113→      );
114→
115→      if (patternMatches.length > 0) {
116→        return {
117→          elements: patternMatches,
118→          source: "accessibility",
119→          tier: 2,
120→          confidence: "high",
121→          fallbackReason: options.debug
122→            ? "no text match, found via resourceId pattern"
123→            : undefined,
124→        };
125→      }
126→    }
127→
128→    if (maxTier === 2) {
129→      return createEarlyStopResult(2, "accessibility");
130→    }
131→  }
132→
133→  // Tier 3: OCR
134→  if ((selector.text || selector.textContains) && maxTier >= 3) {
135→    const searchTerm = selector.text || selector.textContains!;
136→    const screenshotResult = await deps.screenshot(deviceId, {});
137→
138→    try {
139→      const ocrResults = await extractText(screenshotResult.path!);
140→      const matches = searchText(ocrResults, searchTerm);
141→
142→      if (matches.length > 0) {
143→        return {
144→          elements: matches,
145→          source: "ocr",
146→          tier: 3,
147→          confidence: "high",
148→          fallbackReason: options.debug
149→            ? "no accessibility or pattern match, found via OCR"
150→            : undefined,
151→        };
152→      }
153→
154→      if (maxTier === 3) {
155→        return createEarlyStopResult(3, "ocr");
156→      }
157→
158→      // Tier 4: Visual candidates (unlabeled clickables)
159→      const tree = await deps.dump(deviceId);
160→      const flat = flattenTree(tree);
161→      const iconCandidates = filterIconCandidates(flat);
162→
163→      if (iconCandidates.length > 0) {
164→        const candidates: VisualCandidate[] = await Promise.all(
165→          iconCandidates.map(async (node, index) => ({
166→            index,
167→            bounds: formatBounds(node),
168→            center: { x: node.centerX, y: node.centerY },
169→            image: await cropCandidateImage(screenshotResult.path!, node.bounds),
170→          }))
171→        );
172→
173→        const allUnlabeled = flat.filter((n) => n.clickable && !n.text && !n.contentDesc);
174→
175→        return {
176→          elements: [],
177→          source: "visual",
178→          tier: 4,
179→          confidence: "medium",
180→          candidates,
181→          truncated: iconCandidates.length < allUnlabeled.length,
182→          totalCandidates: allUnlabeled.length,
183→          fallbackReason: options.debug
184→            ? "no text/pattern/OCR match, showing visual candidates"
185→            : undefined,
186→        };
187→      }
188→
189→      if (maxTier === 4) {
190→        return createEarlyStopResult(4, "visual");
191→      }
192→
193→      // Tier 5: Grid fallback
194→      const gridImage = await createGridOverlay(screenshotResult.path!);
195→
196→      return {
197→        elements: [],
198→        source: "grid",
199→        tier: 5,
200→        confidence: "low",
201→        gridImage,
202→        gridPositions: POSITION_LABELS,
203→        fallbackReason: options.debug
204→          ? "no usable elements, showing grid for coordinate selection"
205→          : undefined,
206→      };
207→    } finally {
208→      if (screenshotResult.path) {
209→        const fs = await import("fs/promises");
210→        await fs.unlink(screenshotResult.path).catch(() => {});
211→      }
212→    }
213→  }
214→
215→  // No text selector - return empty with visual fallback if requested
216→  if (options.includeVisualFallback) {
217→    const snapshot = await deps.visualSnapshot(deviceId, {
218→      includeBase64: options.includeBase64,
219→    });
220→
221→    return {
222→      elements: [],
223→      source: "accessibility",
224→      tier: 1,
225→      confidence: "high",
226→      visualFallback: {
227→        ...snapshot,
228→        hint: "No elements matched selector. Use screenshot to identify tap coordinates.",
229→      },
230→    };
231→  }
232→
233→  return {
234→    elements: [],
235→    source: "accessibility",
236→    tier: 1,
237→    confidence: "high",
238→  };
239→}
