 1→import { z } from "zod";
 2→import { ServerContext } from "../server.js";
 3→
 4→export const adbShellInputSchema = z.object({
 5→  command: z.string(),
 6→  timeout: z.number().optional(),
 7→  maxChars: z.number().min(1).optional(),
 8→  summaryOnly: z.boolean().optional(),
 9→  previewChars: z.number().min(1).optional(),
10→});
11→
12→export type AdbShellInput = z.infer<typeof adbShellInputSchema>;
13→
14→export async function handleAdbShellTool(
15→  input: AdbShellInput,
16→  context: ServerContext
17→): Promise<Record<string, unknown>> {
18→  const device = await context.deviceState.ensureDevice(context.adb);
19→  const deviceId = device.id;
20→
21→  const result = await context.adb.shell(deviceId, input.command, input.timeout);
22→
23→  if (input.summaryOnly) {
24→    const previewChars = input.previewChars ?? 200;
25→    return {
26→      exitCode: result.exitCode,
27→      deviceId,
28→      summarized: true,
29→      stdoutPreview: result.stdout.slice(0, previewChars),
30→      stderrPreview: result.stderr.slice(0, previewChars),
31→      originalStdoutChars: result.stdout.length,
32→      originalStderrChars: result.stderr.length,
33→    };
34→  }
35→
36→  const maxChars = input.maxChars;
37→  const stdout = maxChars ? result.stdout.slice(0, maxChars) : result.stdout;
38→  const stderr = maxChars ? result.stderr.slice(0, maxChars) : result.stderr;
39→  const truncated = !!maxChars && (result.stdout.length > maxChars || result.stderr.length > maxChars);
40→
41→  const response: Record<string, unknown> = {
42→    stdout,
43→    stderr,
44→    exitCode: result.exitCode,
45→    deviceId,
46→    truncated,
47→  };
48→
49→  if (maxChars !== undefined) {
50→    response.originalStdoutChars = result.stdout.length;
51→    response.originalStderrChars = result.stderr.length;
52→  }
53→
54→  return response;
55→}
