58→  name: "adb-shell",
59→  description: "Execute shell commands with safety guards. Auto-selects device if only one connected. Dangerous commands are blocked.",
60→  inputSchema: {
61→    type: "object",
62→    properties: {
63→      command: { type: "string", description: "Shell command to execute" },
64→      timeout: { type: "number", description: "Timeout in ms (default: 30s, max: 120s)" },
65→      maxChars: { type: "number", description: "Truncate stdout/stderr to at most this many characters" },
66→      summaryOnly: { type: "boolean", description: "Return only compact previews and counts, omitting full stdout/stderr" },
67→      previewChars: { type: "number", description: "For summaryOnly: preview length in characters (default: 200)" },
68→    },
69→    required: ["command"],
70→  },
71→};
