 45→type OperationHandler = (
 46→  input: UiInput,
 47→  context: ServerContext,
 48→  config: UiConfig,
 49→  deviceId: string,
 50→) => Promise<Record<string, unknown>>;
 51→
 52→const uiOperations: Record<string, OperationHandler> = {
 53→  dump: handleDump,
 54→  find: handleFind,
 55→  tap: handleTap,
 56→  input: handleInput,
 57→  scroll: handleScroll,
 58→  screenshot: handleScreenshot,
 59→  "accessibility-check": handleAccessibilityCheck,
