208→async function handleInput(
209→  input: UiInput,
210→  context: ServerContext,
211→  _config: UiConfig,
212→  deviceId: string
213→): Promise<Record<string, unknown>> {
214→  if (!input.text) {
215→    throw new ReplicantError(
216→      ErrorCode.INPUT_VALIDATION_FAILED,
217→      "text is required for input operation",
218→      "Provide the text string to input",
219→    );
220→  }
221→  await context.ui.input(deviceId, input.text);
222→  return { input: input.text, deviceId };
223→}
