225→async function handleScroll(
226→  input: UiInput,
227→  context: ServerContext,
228→  _config: UiConfig,
229→  deviceId: string
230→): Promise<Record<string, unknown>> {
231→  if (!input.direction) {
232→    throw new ReplicantError(
233→      ErrorCode.INPUT_VALIDATION_FAILED,
234→      "direction is required for scroll operation",
235→      "Provide a direction: up, down, left, or right",
236→    );
237→  }
238→  const amount = input.amount ?? 0.5;
239→  await context.ui.scroll(deviceId, input.direction, amount);
240→  return { scrolled: { direction: input.direction, amount }, deviceId };
241→}
