  4→import { TestResult } from "../parsers/gradle-output.js";
  5→import {
  6→  saveBaseline,
  7→  loadBaseline,
  8→  clearBaseline,
  9→  compareResults,
 10→  BaselineTestResult,
 11→} from "../services/test-baseline.js";
 12→
 13→export const gradleTestInputSchema = z.object({
 14→  operation: z.enum(["unitTest", "connectedTest", "saveBaseline", "clearBaseline"]),
 15→  module: z.string().optional(),
 16→  filter: z.string().optional(),
 17→  taskName: z.string().optional().describe("Task name for baseline operations. Defaults to operation name."),
 18→});
