 22→/**
 23→ * Convert gradle TestResult into BaselineTestResult[] for baseline storage/comparison.
 24→ * Captures both passed and failed test names for accurate regression detection.
 25→ */
 26→export function convertToBaselineResults(result: TestResult): BaselineTestResult[] {
 27→  const results: BaselineTestResult[] = [];
 28→
 29→  for (const testName of result.passedTests) {
 30→    results.push({ test: testName, status: "pass" });
 31→  }
 32→
 33→  for (const failure of result.failures) {
 34→    results.push({ test: failure.test, status: "fail" });
 35→  }
 36→
 37→  return results;
 38→}
 39→
 40→async function handleRunTests(
 41→  input: GradleTestInput,
 42→  context: ServerContext,
 43→  operation: "unitTest" | "connectedTest"
 44→): Promise<Record<string, unknown>> {
 45→  const { result, fullOutput } = await context.gradle.test(
 46→    operation,
 47→    input.module,
 48→    input.filter
 49→  );
 50→
 51→  // Cache full output for later retrieval
 52→  const testId = context.cache.generateId("test");
 53→  context.cache.set(
 54→    testId,
 55→    { fullOutput, result, operation },
 56→    "test",
 57→    CACHE_TTLS.TEST_RESULTS
 58→  );
 59→
 60→  // Check for regressions against baseline
 61→  const effectiveTaskName = input.taskName || operation;
 62→  const baseline = loadBaseline(effectiveTaskName);
 63→  const baselineResults = convertToBaselineResults(result);
 64→  const regressions = baseline ? compareResults(baseline, baselineResults) : [];
 65→
 66→  return {
 67→    testId,
 68→    summary: {
 69→      passed: result.passed,
 70→      failed: result.failed,
 71→      skipped: result.skipped,
 72→      total: result.total,
 73→      duration: result.duration,
 74→    },
 75→    failures: result.failures,
 76→    regressions,
 77→  };
 78→}
