 80→async function handleSaveBaseline(
 81→  input: GradleTestInput,
 82→  context: ServerContext
 83→): Promise<Record<string, unknown>> {
 84→  // Run tests first to get current results
 85→  const operation = "unitTest" as const;
 86→  const { result, fullOutput } = await context.gradle.test(
 87→    operation,
 88→    input.module,
 89→    input.filter
 90→  );
 91→
 92→  const testId = context.cache.generateId("test");
 93→  context.cache.set(
 94→    testId,
 95→    { fullOutput, result, operation },
 96→    "test",
 97→    CACHE_TTLS.TEST_RESULTS
 98→  );
 99→
100→  const effectiveTaskName = input.taskName || operation;
101→  const baselineResults = convertToBaselineResults(result);
102→  saveBaseline(effectiveTaskName, baselineResults);
103→
104→  return {
105→    testId,
106→    summary: {
107→      passed: result.passed,
108→      failed: result.failed,
109→      skipped: result.skipped,
110→      total: result.total,
111→      duration: result.duration,
112→    },
113→    baselineSaved: effectiveTaskName,
114→    baselineTestCount: baselineResults.length,
115→  };
116→}
