118→function handleClearBaseline(input: GradleTestInput): Record<string, unknown> {
119→  const effectiveTaskName = input.taskName || "unitTest";
120→  clearBaseline(effectiveTaskName);
121→  return { baselineCleared: effectiveTaskName };
