16→  switch (input.operation) {
17→    case "modules": {
18→      const modules = await context.gradle.listModules();
19→      return { modules };
20→    }
21→
22→    case "variants": {
23→      const variants = await context.gradle.listVariants(input.module);
24→      return { variants, module: input.module || "all" };
25→    }
26→
27→    case "tasks": {
28→      const tasks = await context.gradle.listTasks(input.module);
29→
30→      // Cache full task list
31→      const listId = context.cache.generateId("tasks");
32→      context.cache.set(listId, { tasks }, "tasks", CACHE_TTLS.GRADLE_VARIANTS);
33→
34→      // Return categorized summary
35→      const buildTasks = tasks.filter((t) => t.includes("assemble") || t.includes("bundle"));
36→      const testTasks = tasks.filter((t) => t.includes("test") || t.includes("Test"));
37→      const cleanTasks = tasks.filter((t) => t.includes("clean"));
38→
39→      return {
40→        listId,
41→        summary: {
42→          totalTasks: tasks.length,
43→          buildTasks: buildTasks.slice(0, 10),
44→          testTasks: testTasks.slice(0, 10),
45→          cleanTasks: cleanTasks.slice(0, 5),
46→        },
47→        module: input.module || "all",
48→      };
49→    }
50→
51→    default:
52→      throw new ReplicantError(
53→        ErrorCode.INVALID_OPERATION,
54→        `Unknown operation: ${input.operation}`,
