 5→export const adbLogcatInputSchema = z.object({
 6→  lines: z.number().optional().default(100),
 7→  package: z.string().optional(),
 8→  tags: z.array(z.string()).optional(),
 9→  level: z.enum(["verbose", "debug", "info", "warn", "error"]).optional(),
10→  rawFilter: z.string().optional(),
11→  since: z.string().optional(),
12→});
13→
14→export type AdbLogcatInput = z.infer<typeof adbLogcatInputSchema>;
15→
16→export async function handleAdbLogcatTool(
17→  input: AdbLogcatInput,
18→  context: ServerContext
19→): Promise<Record<string, unknown>> {
20→  const device = await context.deviceState.ensureDevice(context.adb);
21→  const deviceId = device.id;
22→
23→  // Build filter string
24→  let filter = "";
25→  if (input.rawFilter) {
26→    filter = input.rawFilter;
27→  } else if (input.tags || input.level) {
28→    const levelMap: Record<string, string> = {
29→      verbose: "V",
30→      debug: "D",
31→      info: "I",
32→      warn: "W",
33→      error: "E",
34→    };
35→    const levelChar = input.level ? levelMap[input.level] : "V";
36→
37→    if (input.tags) {
38→      filter = input.tags.map((tag) => `${tag}:${levelChar}`).join(" ") + " *:S";
39→    } else {
40→      filter = `*:${levelChar}`;
41→    }
42→  }
43→
44→  const output = await context.adb.logcat(deviceId, {
45→    lines: input.lines,
46→    filter: filter || undefined,
47→    since: input.since,
48→    package: input.package,
49→  });
50→
51→  // Cache the full output and return a summary
52→  const logId = context.cache.generateId("logcat");
53→  context.cache.set(logId, { output, deviceId, filter }, "logcat", CACHE_TTLS.LOGCAT);
54→
55→  // Parse log lines
56→  const lines = output.split("\n").filter(Boolean);
57→  const errorCount = lines.filter((l) => l.includes(" E ")).length;
58→  const warnCount = lines.filter((l) => l.includes(" W ")).length;
59→
60→  return {
61→    logId,
62→    summary: {
63→      lineCount: lines.length,
64→      errorCount,
65→      warnCount,
66→    },
67→    preview: lines.slice(0, 20).join("\n"),
68→    deviceId,
69→  };
70→}
