 12→async function handleList(input: AdbDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 13→  const devices = await context.adb.getDevices();
 14→  context.deviceState.autoSelectIfSingle(devices);
 15→  const current = context.deviceState.getCurrentDevice();
 16→  return {
 17→    devices,
 18→    currentDevice: current?.id || null,
 19→    autoSelected: devices.length === 1,
 20→  };
 21→}
 22→
 23→async function handleSelect(input: AdbDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 24→  if (!input.deviceId) {
 25→    throw new ReplicantError(
 26→      ErrorCode.INPUT_VALIDATION_FAILED,
 27→      "deviceId is required for select operation",
 28→      "Use adb-device list to see available devices, then provide a deviceId",
 29→    );
 30→  }
 31→  const devices = await context.adb.getDevices();
 32→  const device = devices.find((d) => d.id === input.deviceId);
 33→  if (!device) {
 34→    throw new ReplicantError(
 35→      ErrorCode.DEVICE_NOT_FOUND,
 36→      `Device ${input.deviceId} not found`,
 37→      "Use adb-device list to see available devices",
 38→    );
 39→  }
 40→  context.deviceState.setCurrentDevice(device);
 41→  return { selected: device };
 42→}
 43→
 44→async function handleWait(input: AdbDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 45→  const device = input.deviceId
 46→    ? { id: input.deviceId }
 47→    : await context.deviceState.ensureDevice(context.adb);
 48→  const deviceId = device.id;
 49→  await context.adb.waitForDevice(deviceId);
 50→  return { status: "device ready", deviceId };
 51→}
 52→
 53→async function handleProperties(input: AdbDeviceInput, context: ServerContext): Promise<Record<string, unknown>> {
 54→  const device = input.deviceId
 55→    ? { id: input.deviceId }
 56→    : await context.deviceState.ensureDevice(context.adb);
 57→  const deviceId = device.id;
 58→  const props = await context.adb.getProperties(deviceId);
 59→
 60→  const cacheId = context.cache.generateId("device-props");
 61→  context.cache.set(
 62→    cacheId,
 63→    { deviceId, properties: props },
 64→    "device-props",
 65→    CACHE_TTLS.DEVICE_PROPERTIES
 66→  );
 67→
 68→  return {
 69→    deviceId,
 70→    summary: {
 71→      model: props["ro.product.model"],
 72→      manufacturer: props["ro.product.manufacturer"],
 73→      sdkVersion: props["ro.build.version.sdk"],
 74→      androidVersion: props["ro.build.version.release"],
 75→      buildId: props["ro.build.id"],
 76→      device: props["ro.product.device"],
 77→      product: props["ro.product.name"],
 78→      hardware: props["ro.hardware"],
 79→      abiList: props["ro.product.cpu.abilist"],
 80→    },
 81→    propertyCount: Object.keys(props).length,
 82→    cacheId,
 83→  };
