  1→import { z } from "zod";
  2→import { ServerContext } from "../server.js";
  3→import { CACHE_TTLS, UiConfig, ReplicantError, ErrorCode } from "../types/index.js";
  4→import { AccessibilityNode, flattenTree } from "../parsers/ui-dump.js";
  5→import { handleFind, getElementCenter } from "./ui-find.js";
  6→
  7→export const uiInputSchema = z.object({
  8→  operation: z.enum(["dump", "find", "tap", "input", "scroll", "screenshot", "accessibility-check", "visual-snapshot"]),
  9→  selector: z.object({
 10→    resourceId: z.string().optional(),
 11→    text: z.string().optional(),
 12→    textContains: z.string().optional(),
 13→    className: z.string().optional(),
 14→    nearestTo: z.string().optional(),
 15→  }).optional(),
 16→  x: z.number().optional(),
 17→  y: z.number().optional(),
 18→  elementIndex: z.number().optional(),
 19→  text: z.string().optional(),
 20→  localPath: z.string().optional(),
 21→  inline: z.boolean().optional(),
 22→  debug: z.boolean().optional(),
 23→  maxTier: z.number().min(1).max(5).optional(),
 24→  gridCell: z.number().min(1).max(24).optional(),
 25→  gridPosition: z.number().min(1).max(5).optional(),
 26→  deviceSpace: z.boolean().optional(),
 27→  maxDimension: z.number().optional(),
 28→  raw: z.boolean().optional(),
 29→  compact: z.boolean().optional(),
 30→  direction: z.enum(["up", "down", "left", "right"]).optional(),
 31→  amount: z.number().min(0).max(1).optional(),
 32→  limit: z.number().min(1).max(100).optional(),
 33→  offset: z.number().min(0).optional(),
 34→});
 35→
 36→export type UiInput = z.infer<typeof uiInputSchema>;
 37→
 38→const DEFAULT_CONFIG: UiConfig = {
 39→  visualModePackages: [],
 40→  autoFallbackScreenshot: true,
 41→  includeBase64: false,
 42→  maxImageDimension: 800,
 43→};
 44→
 45→type OperationHandler = (
 46→  input: UiInput,
 47→  context: ServerContext,
 48→  config: UiConfig,
 49→  deviceId: string,
 50→) => Promise<Record<string, unknown>>;
 51→
 52→const uiOperations: Record<string, OperationHandler> = {
 53→  dump: handleDump,
 54→  find: handleFind,
 55→  tap: handleTap,
 56→  input: handleInput,
 57→  scroll: handleScroll,
 58→  screenshot: handleScreenshot,
 59→  "accessibility-check": handleAccessibilityCheck,
 60→  "visual-snapshot": handleVisualSnapshot,
 61→};
 62→
 63→export async function handleUiTool(
 64→  input: UiInput,
 65→  context: ServerContext,
 66→  uiConfig?: UiConfig
 67→): Promise<Record<string, unknown>> {
 68→  const device = await context.deviceState.ensureDevice(context.adb);
 69→  const config = uiConfig ?? DEFAULT_CONFIG;
 70→
 71→  const handler = uiOperations[input.operation];
 72→  if (!handler) {
 73→    throw new ReplicantError(
 74→      ErrorCode.INVALID_OPERATION,
 75→      `Unknown operation: ${input.operation}`,
 76→      "Valid operations: dump, find, tap, input, scroll, screenshot, accessibility-check, visual-snapshot",
 77→    );
 78→  }
 79→  return handler(input, context, config, device.id);
 80→}
 81→
 82→async function handleDump(
 83→  input: UiInput,
 84→  context: ServerContext,
 85→  _config: UiConfig,
 86→  deviceId: string
 87→): Promise<Record<string, unknown>> {
 88→  const tree = await context.ui.dump(deviceId);
 89→
 90→  const dumpId = context.cache.generateId("ui-dump");
 91→  context.cache.set(dumpId, { tree, deviceId }, "ui-dump", CACHE_TTLS.UI_TREE);
 92→
 93→  const emptyWarning = tree.length === 0
 94→    ? "No accessibility nodes found. Possible causes: (1) UI still loading - wait and retry, (2) App uses custom rendering (Flutter, games, video players) - use screenshot instead, (3) App blocks accessibility services."
 95→    : undefined;
 96→
 97→  if (input.compact !== false) {
 98→    return handleCompactDump(tree, input, dumpId, deviceId, emptyWarning);
 99→  }
100→
101→  return handleFullDump(tree, dumpId, deviceId, emptyWarning);
102→}
103→
104→function handleCompactDump(
105→  tree: AccessibilityNode[],
106→  input: UiInput,
107→  dumpId: string,
108→  deviceId: string,
109→  emptyWarning: string | undefined
110→): Record<string, unknown> {
111→  const flat = flattenTree(tree);
112→  const interactive = flat.filter((n) => n.clickable || n.focusable);
113→
114→  const limit = input.limit ?? 20;
115→  const offset = input.offset ?? 0;
116→  const totalCount = interactive.length;
117→  const paginated = interactive.slice(offset, offset + limit);
118→  const hasMore = offset + limit < totalCount;
119→
120→  const elements = paginated.map((n) => ({
121→    text: n.text || n.contentDesc || undefined,
122→    type: n.className.split(".").pop(),
123→    x: n.centerX,
124→    y: n.centerY,
125→    resourceId: n.resourceId ? n.resourceId.split("/").pop() : undefined,
126→  }));
127→
128→  const noInteractiveWarning = tree.length > 0 && totalCount === 0
129→    ? "Accessibility tree exists but no interactive elements found. Try 'ui find' with a text selector, or use screenshot for visual targeting."
130→    : undefined;
131→
132→  const hint = hasMore
133→    ? `${elements.length} of ${totalCount} elements shown. Use 'ui find' for specific elements, or add offset: ${offset + limit} for more.`
134→    : undefined;
135→
136→  return {
137→    dumpId,
138→    elements,
139→    count: elements.length,
140→    totalCount,
141→    hasMore,
142→    offset,
143→    limit,
144→    deviceId,
145→    hint,
146→    warning: emptyWarning || noInteractiveWarning,
147→  };
148→}
149→
150→function handleFullDump(
151→  tree: AccessibilityNode[],
152→  dumpId: string,
153→  deviceId: string,
154→  emptyWarning: string | undefined
155→): Record<string, unknown> {
156→  const simplifyNode = (node: AccessibilityNode): Record<string, unknown> => ({
157→    className: node.className.split(".").pop(),
158→    text: node.text || undefined,
159→    resourceId: node.resourceId ? node.resourceId.split("/").pop() : undefined,
160→    bounds: `[${node.bounds.left},${node.bounds.top}][${node.bounds.right},${node.bounds.bottom}]`,
161→    clickable: node.clickable || undefined,
162→    children: node.children?.map((c) => simplifyNode(c)),
163→  });
164→
165→  return {
166→    dumpId,
167→    tree: tree.map((n) => simplifyNode(n)),
168→    deviceId,
169→    warning: emptyWarning,
170→  };
171→}
172→
173→async function handleTap(
174→  input: UiInput,
175→  context: ServerContext,
176→  _config: UiConfig,
177→  deviceId: string
178→): Promise<Record<string, unknown>> {
179→  let x: number, y: number;
180→
181→  if (input.elementIndex !== undefined) {
182→    if (!context.lastFindResults[input.elementIndex]) {
183→      throw new ReplicantError(
184→        ErrorCode.ELEMENT_NOT_FOUND,
185→        `Element at index ${input.elementIndex} not found. Run 'find' first.`,
186→        "Use 'ui find' to locate elements, then reference them by index",
187→      );
188→    }
189→    const element = context.lastFindResults[input.elementIndex];
190→    const center = getElementCenter(element);
191→    x = center.x;
192→    y = center.y;
193→  } else if (input.x !== undefined && input.y !== undefined) {
194→    x = input.x;
195→    y = input.y;
196→  } else {
197→    throw new ReplicantError(
198→      ErrorCode.INPUT_VALIDATION_FAILED,
199→      "Either x/y coordinates or elementIndex is required for tap",
200→      "Provide x and y coordinates, or use elementIndex from a previous 'ui find' result",
201→    );
202→  }
203→
204→  await context.ui.tap(deviceId, x, y, input.deviceSpace);
205→  return { tapped: { x, y, deviceSpace: input.deviceSpace ?? false }, deviceId };
206→}
207→
208→async function handleInput(
209→  input: UiInput,
210→  context: ServerContext,
211→  _config: UiConfig,
212→  deviceId: string
213→): Promise<Record<string, unknown>> {
214→  if (!input.text) {
215→    throw new ReplicantError(
216→      ErrorCode.INPUT_VALIDATION_FAILED,
217→      "text is required for input operation",
218→      "Provide the text string to input",
219→    );
220→  }
221→  await context.ui.input(deviceId, input.text);
222→  return { input: input.text, deviceId };
223→}
224→
225→async function handleScroll(
226→  input: UiInput,
227→  context: ServerContext,
228→  _config: UiConfig,
229→  deviceId: string
230→): Promise<Record<string, unknown>> {
231→  if (!input.direction) {
232→    throw new ReplicantError(
233→      ErrorCode.INPUT_VALIDATION_FAILED,
234→      "direction is required for scroll operation",
235→      "Provide a direction: up, down, left, or right",
236→    );
237→  }
238→  const amount = input.amount ?? 0.5;
239→  await context.ui.scroll(deviceId, input.direction, amount);
240→  return { scrolled: { direction: input.direction, amount }, deviceId };
241→}
242→
243→async function handleScreenshot(
244→  input: UiInput,
245→  context: ServerContext,
246→  config: UiConfig,
247→  deviceId: string
248→): Promise<Record<string, unknown>> {
249→  const result = await context.ui.screenshot(deviceId, {
250→    localPath: input.localPath,
251→    inline: input.inline ?? false,
252→    maxDimension: input.maxDimension ?? config.maxImageDimension,
253→    raw: input.raw,
254→  });
255→  return { ...result, deviceId };
256→}
257→
258→async function handleAccessibilityCheck(
259→  _input: UiInput,
260→  context: ServerContext,
261→  _config: UiConfig,
262→  deviceId: string
263→): Promise<Record<string, unknown>> {
264→  const result = await context.ui.accessibilityCheck(deviceId);
265→  return { ...result, deviceId };
266→}
267→
268→async function handleVisualSnapshot(
269→  input: UiInput,
270→  context: ServerContext,
271→  config: UiConfig,
272→  deviceId: string
273→): Promise<Record<string, unknown>> {
274→  const snapshot = await context.ui.visualSnapshot(deviceId, {
275→    includeBase64: input.inline ?? config.includeBase64,
276→  });
277→  return { ...snapshot, deviceId };
278→}
