 1→import { z } from "zod";
 2→import { CacheManager } from "../services/index.js";
 3→import { ReplicantError, ErrorCode } from "../types/index.js";
 4→
 5→export const cacheInputSchema = z.object({
 6→  operation: z.enum(["get-stats", "clear", "get-config", "set-config"]),
 7→  key: z.string().optional(),
 8→  config: z.object({
 9→    maxEntries: z.number().optional(),
10→    maxEntrySizeBytes: z.number().optional(),
11→    defaultTtlMs: z.number().optional(),
12→  }).optional(),
13→});
14→
15→export type CacheInput = z.infer<typeof cacheInputSchema>;
16→
17→export async function handleCacheTool(
18→  input: CacheInput,
19→  cache: CacheManager
20→): Promise<Record<string, unknown>> {
21→  switch (input.operation) {
22→    case "get-stats":
23→      return { stats: cache.getStats() };
24→
25→    case "clear":
26→      if (input.key) {
27→        cache.clear(input.key);
28→        return { cleared: input.key };
29→      } else {
30→        cache.clearAll();
31→        return { cleared: "all" };
32→      }
33→
34→    case "get-config":
35→      return { config: cache.getConfig() };
36→
37→    case "set-config":
38→      if (input.config) {
39→        cache.setConfig(input.config);
40→      }
41→      return { config: cache.getConfig() };
42→
43→    default:
44→      throw new ReplicantError(
45→        ErrorCode.INVALID_OPERATION,
46→        `Unknown operation: ${input.operation}`,
47→        "Valid operations: get-stats, clear, get-config, set-config",
48→      );
49→  }
50→}
